export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-interactive-colormap-adjustment":{"intro":"In this lab, you will learn how to use Matplotlib to interactively adjust the range of colormapping on an image using a colorbar. You will use the zoom and pan mode to adjust the vmin and vmax of the norm. Zooming using the right mouse button will expand the vmin and vmax proportionally to the selected region. When panning, the vmin and vmax of the norm are both shifted according to the direction of movement. You can also use the Home/Back/Forward buttons to get back to a previous state.","steps":[{"title":"Import Required Libraries","body":["To get started with this lab, you need to import the required libraries. In this lab, we will use matplotlib.pyplot and numpy libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["Next, you will generate some sample data. In this lab, we will generate a two-dimensional sine wave."],"code":[{"lang":"python","text":"t = np.linspace(0, 2 * np.pi, 1024)\ndata2d = np.sin(t)[:, np.newaxis] * np.cos(t)[np.newaxis, :]"}]},{"title":"Create the Plot","body":["Now that you have generated the data, you will create the plot using imshow() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nim = ax.imshow(data2d)\nax.set_title('Pan on the colorbar to shift the color mapping\\n'\n             'Zoom on the colorbar to scale the color mapping')"}]},{"title":"Add the Colorbar","body":["To interactively adjust the colormap, you need to add a colorbar to the plot using colorbar() function."],"code":[{"lang":"python","text":"fig.colorbar(im, ax=ax, label='Interactive colorbar')"}]},{"title":"Display the Plot","body":["Finally, you can display the plot using show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-colormap-normalizations":{"intro":"In this lab, we will learn how to use Matplotlib to map colormaps onto data in non-linear ways. We will demonstrate the use of norm to create logarithmic, power-law, symmetric logarithmic, and custom normalizations. We will also learn how to use BoundaryNorm to provide boundaries for colors.","steps":[{"title":"Lognorm","body":["We will create a low hump with a spike coming out of the top, which needs to have the z/color axis on a log scale, so that we see both the hump and the spike."],"code":[{"lang":"python","text":"N = 100\nX, Y = np.mgrid[-3:3:complex(0, N), -2:2:complex(0, N)]\n\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X * 10)**2 - (Y * 10)**2)\nZ = Z1 + 50 * Z2\n\nfig, ax = plt.subplots(2, 1)\n\npcm = ax[0].pcolor(X, Y, Z,\n                   norm=colors.LogNorm(vmin=Z.min(), vmax=Z.max()),\n                   cmap='PuBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[0], extend='max')\n\npcm = ax[1].pcolor(X, Y, Z, cmap='PuBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[1], extend='max')"}]},{"title":"PowerNorm","body":["We will create a power-law trend in X that partially obscures a rectified sine wave in Y. We will then remove the power-law using a PowerNorm."],"code":[{"lang":"python","text":"X, Y = np.mgrid[0:3:complex(0, N), 0:2:complex(0, N)]\nZ1 = (1 + np.sin(Y * 10.)) * X**2\n\nfig, ax = plt.subplots(2, 1)\n\npcm = ax[0].pcolormesh(X, Y, Z1, norm=colors.PowerNorm(gamma=1. / 2.),\n                       cmap='PuBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[0], extend='max')\n\npcm = ax[1].pcolormesh(X, Y, Z1, cmap='PuBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[1], extend='max')"}]},{"title":"SymLogNorm","body":["We will create two humps, one negative and one positive, with the positive hump having 5 times the amplitude. Linearly, we cannot see detail in the negative hump. We will logarithmically scale the positive and negative data separately using a SymLogNorm."],"code":[{"lang":"python","text":"X, Y = np.mgrid[-3:3:complex(0, N), -2:2:complex(0, N)]\nZ = 5 * np.exp(-X**2 - Y**2)\n\nfig, ax = plt.subplots(2, 1)\n\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=colors.SymLogNorm(linthresh=0.03, linscale=0.03,\n                                              vmin=-1.0, vmax=1.0, base=10),\n                       cmap='RdBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[0], extend='both')\n\npcm = ax[1].pcolormesh(X, Y, Z, cmap='RdBu_r', vmin=-np.max(Z),\n                       shading='nearest')\nfig.colorbar(pcm, ax=ax[1], extend='both')"}]},{"title":"Custom Norm","body":["We will create an example with a customized normalization. This example uses the previous example, and normalizes the negative data differently from the positive."],"code":[{"lang":"python","text":"X, Y = np.mgrid[-3:3:complex(0, N), -2:2:complex(0, N)]\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\nZ = (Z1 - Z2) * 2\n\nclass MidpointNormalize(colors.Normalize):\n    def __init__(self, vmin=None, vmax=None, midpoint=None, clip=False):\n        self.midpoint = midpoint\n        super().__init__(vmin, vmax, clip)\n\n    def __call__(self, value, clip=None):\n        x, y = [self.vmin, self.midpoint, self.vmax], [0, 0.5, 1]\n        return np.ma.masked_array(np.interp(value, x, y))\n\nfig, ax = plt.subplots(2, 1)\n\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=MidpointNormalize(midpoint=0.),\n                       cmap='RdBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[0], extend='both')\n\npcm = ax[1].pcolormesh(X, Y, Z, cmap='RdBu_r', vmin=-np.max(Z),\n                       shading='nearest')\nfig.colorbar(pcm, ax=ax[1], extend='both')"}]},{"title":"BoundaryNorm","body":["We will provide boundaries for colors using BoundaryNorm."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(3, 1, figsize=(8, 8))\nax = ax.flatten()\nbounds = np.linspace(-1, 1, 10)\nnorm = colors.BoundaryNorm(boundaries=bounds, ncolors=256)\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=norm,\n                       cmap='RdBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[0], extend='both', orientation='vertical')\n\nbounds = np.array([-0.25, -0.125, 0, 0.5, 1])\nnorm = colors.BoundaryNorm(boundaries=bounds, ncolors=256)\npcm = ax[1].pcolormesh(X, Y, Z, norm=norm, cmap='RdBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[1], extend='both', orientation='vertical')\n\npcm = ax[2].pcolormesh(X, Y, Z, cmap='RdBu_r', vmin=-np.max(Z1),\n                       shading='nearest')\nfig.colorbar(pcm, ax=ax[2], extend='both', orientation='vertical')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(3, 1, figsize=(8, 8))\nax = ax.flatten()\nbounds = np.linspace(-1, 1, 10)\nnorm = colors.BoundaryNorm(boundaries=bounds, ncolors=256)\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=norm,\n                       cmap='RdBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[0], extend='both', orientation='vertical')\n\nbounds = np.array([-0.25, -0.125, 0, 0.5, 1])\nnorm = colors.BoundaryNorm(boundaries=bounds, ncolors=256)\npcm = ax[1].pcolormesh(X, Y, Z, norm=norm, cmap='RdBu_r', shading='nearest')\nfig.colorbar(pcm, ax=ax[1], extend='both', orientation='vertical')\n\npcm = ax[2].pcolormesh(X, Y, Z, cmap='RdBu_r', vmin=-np.max(Z1),\n                       shading='nearest')\nfig.colorbar(pcm, ax=ax[2], extend='both', orientation='vertical')\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-colormap-normalization":{"intro":"In data visualization, colormaps are used to represent numerical data through color. However, sometimes the data distribution may be nonlinear, which can make it difficult to discern the details of the data. In such cases, colormap normalization can be used to map colormaps onto data in nonlinear ways to help visualize the data more accurately. Matplotlib provides several normalization methods, including SymLogNorm and AsinhNorm, which can be used to normalize colormaps. This lab will demonstrate how to use SymLogNorm and AsinhNorm to map colormaps onto nonlinear data.","steps":[{"title":"Import Required Libraries","body":["In this step, we will import the necessary libraries, including Matplotlib, NumPy, and Matplotlib colors."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.colors as colors"}]},{"title":"Create Synthetic Data","body":["In this step, we will create a synthetic dataset consisting of two humps, one negative and one positive, with the positive hump having an amplitude eight times greater than the negative hump. We will then apply SymLogNorm to visualize the data."],"code":[{"lang":"python","text":"def rbf(x, y):\n    return 1.0 / (1 + 5 * ((x ** 2) + (y ** 2)))\n\nN = 200\ngain = 8\nX, Y = np.mgrid[-3:3:complex(0, N), -2:2:complex(0, N)]\nZ1 = rbf(X + 0.5, Y + 0.5)\nZ2 = rbf(X - 0.5, Y - 0.5)\nZ = gain * Z1 - Z2\n\nshadeopts = {'cmap': 'PRGn', 'shading': 'gouraud'}\ncolormap = 'PRGn'\nlnrwidth = 0.5"}]},{"title":"Apply SymLogNorm","body":["In this step, we will apply SymLogNorm to the synthetic data and visualize the results."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(2, 1, sharex=True, sharey=True)\n\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=colors.SymLogNorm(linthresh=lnrwidth, linscale=1,\n                                              vmin=-gain, vmax=gain, base=10),\n                       **shadeopts)\nfig.colorbar(pcm, ax=ax[0], extend='both')\nax[0].text(-2.5, 1.5, 'symlog')\n\npcm = ax[1].pcolormesh(X, Y, Z, vmin=-gain, vmax=gain,\n                       **shadeopts)\nfig.colorbar(pcm, ax=ax[1], extend='both')\nax[1].text(-2.5, 1.5, 'linear')\n\nplt.show()"}]},{"title":"Apply AsinhNorm","body":["In this step, we will apply AsinhNorm to the synthetic data and visualize the results."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(2, 1, sharex=True, sharey=True)\n\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=colors.SymLogNorm(linthresh=lnrwidth, linscale=1,\n                                              vmin=-gain, vmax=gain, base=10),\n                       **shadeopts)\nfig.colorbar(pcm, ax=ax[0], extend='both')\nax[0].text(-2.5, 1.5, 'symlog')\n\npcm = ax[1].pcolormesh(X, Y, Z,\n                       norm=colors.AsinhNorm(linear_width=lnrwidth,\n                                             vmin=-gain, vmax=gain),\n                       **shadeopts)\nfig.colorbar(pcm, ax=ax[1], extend='both')\nax[1].text(-2.5, 1.5, 'asinh')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(2, 1, sharex=True, sharey=True)\n\npcm = ax[0].pcolormesh(X, Y, Z,\n                       norm=colors.SymLogNorm(linthresh=lnrwidth, linscale=1,\n                                              vmin=-gain, vmax=gain, base=10),\n                       **shadeopts)\nfig.colorbar(pcm, ax=ax[0], extend='both')\nax[0].text(-2.5, 1.5, 'symlog')\n\npcm = ax[1].pcolormesh(X, Y, Z,\n                       norm=colors.AsinhNorm(linear_width=lnrwidth,\n                                             vmin=-gain, vmax=gain),\n                       **shadeopts)\nfig.colorbar(pcm, ax=ax[1], extend='both')\nax[1].text(-2.5, 1.5, 'asinh')\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-color-maps":{"intro":"In this lab, you will learn how to create color maps using Matplotlib. Color maps are useful when visualizing data, as they provide a way to represent numerical data through colors. Matplotlib provides a variety of built-in color maps, as well as the ability to create custom color maps.","steps":[{"title":"Understanding Color Maps","body":["A color map is a mapping between a range of numerical values and a range of colors. In Matplotlib, a color map is created using the matplotlib.colors module."],"code":[]},{"title":"Creating a Simple Color Map","body":["To create a simple color map, we can use the ListedColormap class from the matplotlib.colors module. This class takes a list of colors and creates a color map from them."],"code":[{"lang":"python","text":"import matplotlib.colors as mcolors\n\n# Define a list of colors\ncolors = ['red', 'green', 'blue']\n\n# Create a ListedColormap object from the list of colors\ncmap = mcolors.ListedColormap(colors)"}]},{"title":"Using Built-In Color Maps","body":["Matplotlib provides a variety of built-in color maps that can be used to represent data. These color maps can be accessed using their names, which are listed in the matplotlib.cm module."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Create a plot using the 'viridis' color map\nplt.imshow(data, cmap='viridis')\nplt.colorbar()"}]},{"title":"Reversing Color Maps","body":["Matplotlib provides the ability to reverse a color map by appending _r to the name of the color map."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Create a plot using the reversed 'viridis' color map\nplt.imshow(data, cmap='viridis_r')\nplt.colorbar()"}]},{"title":"Creating Custom Color Maps","body":["Matplotlib also provides the ability to create custom color maps. This can be useful when the built-in color maps do not provide the desired representation of the data."],"code":[{"lang":"python","text":"import matplotlib.colors as mcolors\n\n# Define a list of colors and their corresponding values\ncolors = [(0, 'red'), (0.5, 'green'), (1, 'blue')]\n\n# Create a LinearSegmentedColormap object from the list of colors\ncmap = mcolors.LinearSegmentedColormap.from_list('my_cmap', colors)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.colors as mcolors\n\n# Define a list of colors and their corresponding values\ncolors = [(0, 'red'), (0.5, 'green'), (1, 'blue')]\n\n# Create a LinearSegmentedColormap object from the list of colors\ncmap = mcolors.LinearSegmentedColormap.from_list('my_cmap', colors)"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-a-compound-path":{"intro":"In this tutorial, we will learn how to create a compound path using Matplotlib in Python. A compound path is a collection of simple paths that can be used to create complex shapes. We will create a compound path by combining two simple polygons, a rectangle, and a triangle.","steps":[{"title":"Importing the Required Libraries","body":["Importing the Required Libraries","We will start by importing the required libraries. We need matplotlib.pyplot for creating the plot, matplotlib.patches for creating patches, matplotlib.path.Path for creating paths, and numpy for creating arrays."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.patches import PathPatch\nfrom matplotlib.path import Path\nimport numpy as np"}]},{"title":"Creating the Vertices and Codes","body":["Creating the Vertices and Codes","We will create the vertices and codes for the two polygons that we want to combine into a compound path. We will use Path.MOVETO to move the cursor to the starting point of the polygon, Path.LINETO to create a line from the starting point to the next point, and Path.CLOSEPOLY to close the polygon."],"code":[{"lang":"python","text":"vertices = []\ncodes = []\n\n# First Polygon - Rectangle\ncodes = [Path.MOVETO] + [Path.LINETO]*3 + [Path.CLOSEPOLY]\nvertices = [(1, 1), (1, 2), (2, 2), (2, 1), (0, 0)]\n\n# Second Polygon - Triangle\ncodes += [Path.MOVETO] + [Path.LINETO]*2 + [Path.CLOSEPOLY]\nvertices += [(4, 4), (5, 5), (5, 4), (0, 0)]"}]},{"title":"Creating the Path","body":["We will use Path to create the path from the vertices and codes that we created in the previous step."],"code":[{"lang":"python","text":"path = Path(vertices, codes)"}]},{"title":"Creating the PathPatch","body":["We will create a PathPatch from the path that we created in the previous step. We will set the facecolor to 'none' and the edgecolor to 'green'."],"code":[{"lang":"python","text":"pathpatch = PathPatch(path, facecolor='none', edgecolor='green')"}]},{"title":"Creating the Plot","body":["We will create the plot and add the PathPatch to the plot. We will set the title of the plot to 'A Compound Path'."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.add_patch(pathpatch)\nax.set_title('A Compound Path')\n\nax.autoscale_view()\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.add_patch(pathpatch)\nax.set_title('A Compound Path')\n\nax.autoscale_view()\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-plotting-confidence-ellipses-with-matplotlib":{"intro":"This lab will demonstrate how to plot confidence ellipses of a two-dimensional dataset using Python Matplotlib. A confidence ellipse is a graphical representation of the covariance of a dataset, showing the uncertainty of the estimated mean and standard deviation. The ellipses are plotted using the Pearson correlation coefficient.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the necessary libraries. We will need numpy and matplotlib.pyplot for this lab."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the confidence_ellipse Function","body":["Define the confidence_ellipse Function","Next, we define the confidence_ellipse function that will take in the x and y coordinates of the dataset, the axes object to draw the ellipse into, and the number of standard deviations. It returns a Matplotlib patch object representing the ellipse."],"code":[{"lang":"python","text":"def confidence_ellipse(x, y, ax, n_std=3.0, facecolor='none', **kwargs):\n    \"\"\"\n    Create a plot of the covariance confidence ellipse of *x* and *y*.\n\n    Parameters\n    ----------\n    x, y : array-like, shape (n, )\n        Input data.\n\n    ax : matplotlib.axes.Axes\n        The axes object to draw the ellipse into.\n\n    n_std : float\n        The number of standard deviations to determine the ellipse's radiuses.\n\n    **kwargs\n        Forwarded to `~matplotlib.patches.Ellipse`\n\n    Returns\n    -------\n    matplotlib.patches.Ellipse\n    \"\"\"\n    if x.size != y.size:\n        raise ValueError(\"x and y must be the same size\")\n\n    cov = np.cov(x, y)\n    pearson = cov[0, 1]/np.sqrt(cov[0, 0] * cov[1, 1])\n    # Using a special case to obtain the eigenvalues of this\n    # two-dimensional dataset.\n    ell_radius_x = np.sqrt(1 + pearson)\n    ell_radius_y = np.sqrt(1 - pearson)\n    ellipse = Ellipse((0, 0), width=ell_radius_x * 2, height=ell_radius_y * 2,\n                      facecolor=facecolor, **kwargs)\n\n    # Calculating the standard deviation of x from\n    # the squareroot of the variance and multiplying\n    # with the given number of standard deviations.\n    scale_x = np.sqrt(cov[0, 0]) * n_std\n    mean_x = np.mean(x)\n\n    # calculating the standard deviation of y ...\n    scale_y = np.sqrt(cov[1, 1]) * n_std\n    mean_y = np.mean(y)\n\n    transf = transforms.Affine2D() \\\n        .rotate_deg(45) \\\n        .scale(scale_x, scale_y) \\\n        .translate(mean_x, mean_y)"}]},{"title":"Define the get_correlated_dataset Function","body":["Define the get_correlated_dataset Function","We also need a function to generate a two-dimensional dataset with specified mean, dimensions, and correlation."],"code":[{"lang":"python","text":"def get_correlated_dataset(n, dependency, mu, scale):\n    \"\"\"\n    Creates a random two-dimensional dataset with the specified\n    two-dimensional mean (mu) and dimensions (scale).\n    The correlation can be controlled by the param 'dependency',\n    a 2x2 matrix.\n    \"\"\"\n    latent = np.random.randn(n, 2)\n    dependent = latent.dot(dependency)\n    scaled = dependent * scale\n    scaled_with_offset = scaled + mu\n    # return x and y of the new, correlated dataset\n    return scaled_with_offset[:, 0], scaled_with_offset[:, 1]"}]},{"title":"Plotting Positive, Negative, and Weak Correlations","body":["Plotting Positive, Negative, and Weak Correlations","Now, we can use these functions to plot the confidence ellipses of datasets with positive, negative, and weak correlations."],"code":[{"lang":"python","text":"np.random.seed(0)\n\nPARAMETERS = {\n    'Positive correlation': [[0.85, 0.35],\n                             [0.15, -0.65]],\n    'Negative correlation': [[0.9, -0.4],\n                             [0.1, -0.6]],\n    'Weak correlation': [[1, 0],\n                         [0, 1]],\n}\n\nmu = 2, 4\nscale = 3, 5\n\nfig, axs = plt.subplots(1, 3, figsize=(9, 3))\nfor ax, (title, dependency) in zip(axs, PARAMETERS.items()):\n    x, y = get_correlated_dataset(800, dependency, mu, scale)\n    ax.scatter(x, y, s=0.5)\n\n    ax.axvline(c='grey', lw=1)\n    ax.axhline(c='grey', lw=1)\n\n    confidence_ellipse(x, y, ax, edgecolor='red')\n\n    ax.scatter(mu[0], mu[1], c='red', s=3)\n    ax.set_title(title)\n\nplt.show()"}]},{"title":"Plotting Different Number of Standard Deviations","body":["Plotting Different Number of Standard Deviations","We can also plot the confidence ellipses with different number of standard deviations."],"code":[{"lang":"python","text":"fig, ax_nstd = plt.subplots(figsize=(6, 6))\n\ndependency_nstd = [[0.8, 0.75],\n                   [-0.2, 0.35]]\nmu = 0, 0\nscale = 8, 5\n\nax_nstd.axvline(c='grey', lw=1)\nax_nstd.axhline(c='grey', lw=1)\n\nx, y = get_correlated_dataset(500, dependency_nstd, mu, scale)\nax_nstd.scatter(x, y, s=0.5)\n\nconfidence_ellipse(x, y, ax_nstd, n_std=1,\n                   label=r'$1\\sigma$', edgecolor='firebrick')\nconfidence_ellipse(x, y, ax_nstd, n_std=2,\n                   label=r'$2\\sigma$', edgecolor='fuchsia', linestyle='--')\nconfidence_ellipse(x, y, ax_nstd, n_std=3,\n                   label=r'$3\\sigma$', edgecolor='blue', linestyle=':')\n\nax_nstd.scatter(mu[0], mu[1], c='red', s=3)\nax_nstd.set_title('Different standard deviations')\nax_nstd.legend()\nplt.show()"}]},{"title":"Using Keyword Arguments","body":["Lastly, we can customize the appearance of the ellipses using keyword arguments."],"code":[{"lang":"python","text":"fig, ax_kwargs = plt.subplots(figsize=(6, 6))\ndependency_kwargs = [[-0.8, 0.5],\n                     [-0.2, 0.5]]\nmu = 2, -3\nscale = 6, 5\n\nax_kwargs.axvline(c='grey', lw=1)\nax_kwargs.axhline(c='grey', lw=1)\n\nx, y = get_correlated_dataset(500, dependency_kwargs, mu, scale)\n# Plot the ellipse with zorder=0 in order to demonstrate\n# its transparency (caused by the use of alpha).\nconfidence_ellipse(x, y, ax_kwargs,\n                   alpha=0.5, facecolor='pink', edgecolor='purple', zorder=0)\n\nax_kwargs.scatter(x, y, s=0.5)\nax_kwargs.scatter(mu[0], mu[1], c='red', s=3)\nax_kwargs.set_title('Using keyword arguments')\n\nfig.subplots_adjust(hspace=0.25)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax_kwargs = plt.subplots(figsize=(6, 6))\ndependency_kwargs = [[-0.8, 0.5],\n                     [-0.2, 0.5]]\nmu = 2, -3\nscale = 6, 5\n\nax_kwargs.axvline(c='grey', lw=1)\nax_kwargs.axhline(c='grey', lw=1)\n\nx, y = get_correlated_dataset(500, dependency_kwargs, mu, scale)\n# Plot the ellipse with zorder=0 in order to demonstrate\n# its transparency (caused by the use of alpha).\nconfidence_ellipse(x, y, ax_kwargs,\n                   alpha=0.5, facecolor='pink', edgecolor='purple', zorder=0)\n\nax_kwargs.scatter(x, y, s=0.5)\nax_kwargs.scatter(mu[0], mu[1], c='red', s=3)\nax_kwargs.set_title('Using keyword arguments')\n\nfig.subplots_adjust(hspace=0.25)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-connection-patch-visualization":{"intro":"Matplotlib is a powerful data visualization library in Python. It provides a variety of visualization tools to create stunning graphics and charts. In this lab, we will learn about ConnectionPatch, which is used to draw a line between points defined in different coordinate systems and/or axes.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","Before we start, let's import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.patches import ConnectionPatch"}]},{"title":"Create the plot","body":["Next, let's create the plot with two subplots."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(6, 3))"}]},{"title":"Draw a simple arrow","body":["Now, let's draw a simple arrow between two points in axes coordinates within a single axes."],"code":[{"lang":"python","text":"xyA = (0.2, 0.2)\nxyB = (0.8, 0.8)\ncoordsA = \"data\"\ncoordsB = \"data\"\ncon = ConnectionPatch(xyA, xyB, coordsA, coordsB,\n                      arrowstyle=\"-|>\", shrinkA=5, shrinkB=5,\n                      mutation_scale=20, fc=\"w\")\nax1.plot([xyA[0], xyB[0]], [xyA[1], xyB[1]], \"o\")\nax1.add_artist(con)"}]},{"title":"Draw an arrow between different axes","body":["Draw an arrow between different axes","Let's draw an arrow between the same point in data coordinates, but in different axes."],"code":[{"lang":"python","text":"xy = (0.3, 0.2)\ncon = ConnectionPatch(\n    xyA=xy, coordsA=ax2.transData,\n    xyB=xy, coordsB=ax1.transData,\n    arrowstyle=\"->\", shrinkB=5)\nfig.add_artist(con)"}]},{"title":"Draw a line between the different points","body":["Draw a line between the different points","Finally, let's draw a line between the different points, defined in different coordinate systems."],"code":[{"lang":"python","text":"con = ConnectionPatch(\n    # in axes coordinates\n    xyA=(0.6, 1.0), coordsA=ax2.transAxes,\n    # x in axes coordinates, y in data coordinates\n    xyB=(0.0, 0.2), coordsB=ax2.get_yaxis_transform(),\n    arrowstyle=\"-\")\nax2.add_artist(con)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"con = ConnectionPatch(\n    # in axes coordinates\n    xyA=(0.6, 1.0), coordsA=ax2.transAxes,\n    # x in axes coordinates, y in data coordinates\n    xyB=(0.0, 0.2), coordsB=ax2.get_yaxis_transform(),\n    arrowstyle=\"-\")\nax2.add_artist(con)"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotation-connection-styles":{"intro":"This lab will guide you through the process of creating annotation connection styles using the Matplotlib library in Python. Annotations are an important tool in data visualization as they help to explain or highlight specific data points on a graph. The connection style of an annotation refers to the shape and style of the line connecting the annotation to the data point.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","Before we can create our annotations, we need to import the necessary libraries. In this case, we will be using the Matplotlib library."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Define the function for creating annotation connection styles","body":["Define the function for creating annotation connection styles","We will define a function that takes in two parameters: the axis object and the connection style. The function will plot two data points and create an annotation with the specified connection style."],"code":[{"lang":"python","text":"def demo_con_style(ax, connectionstyle):\n    x1, y1 = 0.3, 0.2\n    x2, y2 = 0.8, 0.6\n\n    ax.plot([x1, x2], [y1, y2], \".\")\n    ax.annotate(\"\",\n                xy=(x1, y1), xycoords='data',\n                xytext=(x2, y2), textcoords='data',\n                arrowprops=dict(arrowstyle=\"->\", color=\"0.5\",\n                                shrinkA=5, shrinkB=5,\n                                patchA=None, patchB=None,\n                                connectionstyle=connectionstyle,\n                                ),\n                )\n\n    ax.text(.05, .95, connectionstyle.replace(\",\", \",\\n\"),\n            transform=ax.transAxes, ha=\"left\", va=\"top\")"}]},{"title":"Create the annotation connection styles","body":["Create the annotation connection styles","We will create various annotation connection styles using the demo_con_style function and plot them on a grid."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(3, 5, figsize=(7, 6.3), layout=\"constrained\")\ndemo_con_style(axs[0, 0], \"angle3,angleA=90,angleB=0\")\ndemo_con_style(axs[1, 0], \"angle3,angleA=0,angleB=90\")\ndemo_con_style(axs[0, 1], \"arc3,rad=0.\")\ndemo_con_style(axs[1, 1], \"arc3,rad=0.3\")\ndemo_con_style(axs[2, 1], \"arc3,rad=-0.3\")\ndemo_con_style(axs[0, 2], \"angle,angleA=-90,angleB=180,rad=0\")\ndemo_con_style(axs[1, 2], \"angle,angleA=-90,angleB=180,rad=5\")\ndemo_con_style(axs[2, 2], \"angle,angleA=-90,angleB=10,rad=5\")\ndemo_con_style(axs[0, 3], \"arc,angleA=-90,angleB=0,armA=30,armB=30,rad=0\")\ndemo_con_style(axs[1, 3], \"arc,angleA=-90,angleB=0,armA=30,armB=30,rad=5\")\ndemo_con_style(axs[2, 3], \"arc,angleA=-90,angleB=0,armA=0,armB=40,rad=0\")\ndemo_con_style(axs[0, 4], \"bar,fraction=0.3\")\ndemo_con_style(axs[1, 4], \"bar,fraction=-0.3\")\ndemo_con_style(axs[2, 4], \"bar,angle=180,fraction=-0.2\")\n\nfor ax in axs.flat:\n    ax.set(xlim=(0, 1), ylim=(0, 1.25), xticks=[], yticks=[], aspect=1.25)\nfig.set_constrained_layout_pads(wspace=0, hspace=0, w_pad=0, h_pad=0)\n\nplt.show()"}]},{"title":"Interpret the results","body":["The resulting grid of annotations with different connection styles will be displayed. The annotations help to highlight the data points on the graph and the different styles show the versatility of the annotation feature in Matplotlib."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-masked-contour-plots-with-matplotlib":{"intro":"In data visualization, contour plots are commonly used to display 3-dimensional data on a 2-dimensional plane. Matplotlib is a widely used plotting library in Python that provides functionalities to create different types of plots, including contour plots. In this lab, we will learn how to create masked contour plots using Matplotlib and how to illustrate the difference between corner masks being enabled and disabled.","steps":[{"title":"Importing Required Libraries","body":["To create masked contour plots using Matplotlib, we need to import the following libraries:","• numpy: a library for the Python programming language that provides support for large, multi-dimensional arrays and matrices. • matplotlib.pyplot: a collection of functions that provide a simple interface for creating different types of plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating Data for Plotting","body":["In this step, we will create data to plot on a contour plot. We use the np.meshgrid() function to create a grid of points, and then calculate the z values using the sine and cosine functions."],"code":[{"lang":"python","text":"# Data to plot.\nx, y = np.meshgrid(np.arange(7), np.arange(10))\nz = np.sin(0.5 * x) * np.cos(0.52 * y)"}]},{"title":"Masking the Data","body":["In this step, we will mask some of the z values using a Boolean mask. We create a mask array using the np.zeros_like() function, and then set some of the values to True to mask them."],"code":[{"lang":"python","text":"# Mask various z values.\nmask = np.zeros_like(z, dtype=bool)\nmask[2, 3:5] = True\nmask[3:5, 4] = True\nmask[7, 2] = True\nmask[5, 0] = True\nmask[0, 6] = True\nz = np.ma.array(z, mask=mask)"}]},{"title":"Creating the Plot","body":["In this step, we will create the masked contour plot using the contourf() function. We pass in the x, y, and z arrays to this function, along with the corner_mask argument set to True or False depending on the type of plot we want to create."],"code":[{"lang":"python","text":"corner_masks = [False, True]\nfig, axs = plt.subplots(ncols=2)\nfor ax, corner_mask in zip(axs, corner_masks):\n    cs = ax.contourf(x, y, z, corner_mask=corner_mask)\n    ax.contour(cs, colors='k')\n    ax.set_title(f'{corner_mask=}')\n\n    # Plot grid.\n    ax.grid(c='k', ls='-', alpha=0.3)\n\n    # Indicate masked points with red circles.\n    ax.plot(np.ma.array(x, mask=~mask), y, 'ro')\n\nplt.show()"}]},{"title":"Interpretation of Results","body":["In this step, we will interpret the results of the masked contour plot. We can observe that the corner_mask parameter controls whether or not the corner points of the plot are masked. When corner_mask is set to True, the corners of the contour plot are masked, while when it is set to False, they are not masked. We can also see that the masked points are indicated by red circles."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-contour-plots-with-python-matplotli":{"intro":"This lab is a step-by-step tutorial on how to create contour plots using Python Matplotlib. Contour plots are useful for visualizing three-dimensional data in two dimensions. In this tutorial, we will be illustrating simple contour plotting, contours on an image with a colorbar for the contours, and labeled contours.","steps":[{"title":"Import Required Libraries","body":["Before we can begin creating our contour plot, we need to import the necessary libraries. We will be using numpy and matplotlib for this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["We need to create the data we will be using to create the contour plot. In this example, we will be creating two 2D Gaussian functions."],"code":[{"lang":"python","text":"delta = 0.025\nx = np.arange(-3.0, 3.0, delta)\ny = np.arange(-2.0, 2.0, delta)\nX, Y = np.meshgrid(x, y)\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\nZ = (Z1 - Z2) * 2"}]},{"title":"Create a Simple Contour Plot with Labels","body":["Create a Simple Contour Plot with Labels","Now that we have our data, we can create a simple contour plot with labels using default colors."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nCS = ax.contour(X, Y, Z)\nax.clabel(CS, inline=True, fontsize=10)\nax.set_title('Simplest default with labels')"}]},{"title":"Place Contour Labels Manually","body":["We can also place contour labels manually by providing a list of positions (in data coordinate)."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nCS = ax.contour(X, Y, Z)\nmanual_locations = [\n    (-1, -1.4), (-0.62, -0.7), (-2, 0.5), (1.7, 1.2), (2.0, 1.4), (2.4, 1.7)]\nax.clabel(CS, inline=True, fontsize=10, manual=manual_locations)\nax.set_title('labels at selected locations')"}]},{"title":"Set Contour Colors","body":["We can force all the contours to be the same color or set negative contours to be solid instead of dashed."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nCS = ax.contour(X, Y, Z, 6, colors='k')  # Negative contours default to dashed.\nax.clabel(CS, fontsize=9, inline=True)\nax.set_title('Single color - negative contours dashed')"},{"lang":"python","text":"plt.rcParams['contour.negative_linestyle'] = 'solid'\nfig, ax = plt.subplots()\nCS = ax.contour(X, Y, Z, 6, colors='k')  # Negative contours default to dashed.\nax.clabel(CS, fontsize=9, inline=True)\nax.set_title('Single color - negative contours solid')"}]},{"title":"Manually Specify Contour Colors","body":["Manually Specify Contour Colors","We can also manually specify the colors of the contour."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nCS = ax.contour(X, Y, Z, 6,\n                linewidths=np.arange(.5, 4, .5),\n                colors=('r', 'green', 'blue', (1, 1, 0), '#afeeee', '0.5'),\n                )\nax.clabel(CS, fontsize=9, inline=True)\nax.set_title('Crazy lines')"}]},{"title":"Use a Colormap to Specify Contour Colors","body":["Use a Colormap to Specify Contour Colors","We can use a colormap to specify the colors for the contour lines."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nim = ax.imshow(Z, interpolation='bilinear', origin='lower',\n               cmap=cm.gray, extent=(-3, 3, -2, 2))\nlevels = np.arange(-1.2, 1.6, 0.2)\nCS = ax.contour(Z, levels, origin='lower', cmap='flag', extend='both',\n                linewidths=2, extent=(-3, 3, -2, 2))\n\n# Thicken the zero contour.\nCS.collections[6].set_linewidth(4)\n\nax.clabel(CS, levels[1::2],  # label every second level\n          inline=True, fmt='%1.1f', fontsize=14)\n\n# make a colorbar for the contour lines\nCB = fig.colorbar(CS, shrink=0.8)\n\nax.set_title('Lines with colorbar')\n\n# We can still add a colorbar for the image, too.\nCBI = fig.colorbar(im, orientation='horizontal', shrink=0.8)\n\n# This makes the original colorbar look a bit out of place,\n# so let's improve its position.\n\nl, b, w, h = ax.get_position().bounds\nll, bb, ww, hh = CB.ax.get_position().bounds\nCB.ax.set_position([ll, b + 0.1*h, ww, h*0.8])"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nim = ax.imshow(Z, interpolation='bilinear', origin='lower',\n               cmap=cm.gray, extent=(-3, 3, -2, 2))\nlevels = np.arange(-1.2, 1.6, 0.2)\nCS = ax.contour(Z, levels, origin='lower', cmap='flag', extend='both',\n                linewidths=2, extent=(-3, 3, -2, 2))\n\n# Thicken the zero contour.\nCS.collections[6].set_linewidth(4)\n\nax.clabel(CS, levels[1::2],  # label every second level\n          inline=True, fmt='%1.1f', fontsize=14)\n\n# make a colorbar for the contour lines\nCB = fig.colorbar(CS, shrink=0.8)\n\nax.set_title('Lines with colorbar')\n\n# We can still add a colorbar for the image, too.\nCBI = fig.colorbar(im, orientation='horizontal', shrink=0.8)\n\n# This makes the original colorbar look a bit out of place,\n# so let's improve its position.\n\nl, b, w, h = ax.get_position().bounds\nll, bb, ww, hh = CB.ax.get_position().bounds\nCB.ax.set_position([ll, b + 0.1*h, ww, h*0.8])"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-contour-image":{"intro":"In this lab, you will learn how to create a contour image using Python's Matplotlib library. The contour image is a visualization technique that represents a three-dimensional surface using a two-dimensional plot. The contour image consists of contour lines, which are lines that connect points of equal value in the surface, and filled contours, which are regions between the contour lines.","steps":[{"title":"Import Libraries","body":["In this step, you will import the necessary libraries to create the contour image."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib import cm"}]},{"title":"Define the Data","body":["In this step, you will define the data to be plotted. The data is a two-dimensional array of values that represents the surface."],"code":[{"lang":"python","text":"# Default delta is large because that makes it fast, and it illustrates\n# the correct registration between image and contours.\ndelta = 0.5\n\nextent = (-3, 4, -4, 3)\n\nx = np.arange(-3.0, 4.001, delta)\ny = np.arange(-4.0, 3.001, delta)\nX, Y = np.meshgrid(x, y)\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\nZ = (Z1 - Z2) * 2"}]},{"title":"Create the Contour Image","body":["In this step, you will create the contour image by using Matplotlib's contour and contourf functions."],"code":[{"lang":"python","text":"# Boost the upper limit to avoid truncation errors.\nlevels = np.arange(-2.0, 1.601, 0.4)\n\nnorm = cm.colors.Normalize(vmax=abs(Z).max(), vmin=-abs(Z).max())\ncmap = cm.PRGn\n\nfig, _axs = plt.subplots(nrows=2, ncols=2)\nfig.subplots_adjust(hspace=0.3)\naxs = _axs.flatten()\n\ncset1 = axs[0].contourf(X, Y, Z, levels, norm=norm,\n                        cmap=cmap.resampled(len(levels) - 1))\n# It is not necessary, but for the colormap, we need only the\n# number of levels minus 1.  To avoid discretization error, use\n# either this number or a large number such as the default (256).\n\n# If we want lines as well as filled regions, we need to call\n# contour separately; don't try to change the edgecolor or edgewidth\n# of the polygons in the collections returned by contourf.\n# Use levels output from previous call to guarantee they are the same.\n\ncset2 = axs[0].contour(X, Y, Z, cset1.levels, colors='k')\n\n# We don't really need dashed contour lines to indicate negative\n# regions, so let's turn them off.\n\nfor c in cset2.collections:\n    c.set_linestyle('solid')\n\n# It is easier here to make a separate call to contour than\n# to set up an array of colors and linewidths.\n# We are making a thick green line as a zero contour.\n# Specify the zero level as a tuple with only 0 in it.\n\ncset3 = axs[0].contour(X, Y, Z, (0,), colors='g', linewidths=2)\naxs[0].set_title('Filled contours')\nfig.colorbar(cset1, ax=axs[0])\n\n\naxs[1].imshow(Z, extent=extent, cmap=cmap, norm=norm)\naxs[1].contour(Z, levels, colors='k', origin='upper', extent=extent)\naxs[1].set_title(\"Image, origin 'upper'\")\n\naxs[2].imshow(Z, origin='lower', extent=extent, cmap=cmap, norm=norm)\naxs[2].contour(Z, levels, colors='k', origin='lower', extent=extent)\naxs[2].set_title(\"Image, origin 'lower'\")\n\n# We will use the interpolation \"nearest\" here to show the actual"}]},{"title":"Display the Contour Image","body":["In this step, you will display the contour image."],"code":[{"lang":"python","text":"fig.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customized-matplotlib-contour-labeling":{"intro":"In this tutorial, we will learn how to create contour labels in Matplotlib. Contour labels are used to label the contours in a contour plot. This tutorial will cover some advanced techniques for creating custom contour labels.","steps":[{"title":"Define our surface","body":["We will start by defining our surface using numpy and matplotlib. This will give us a dataset to work with."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ndelta = 0.025\nx = np.arange(-3.0, 3.0, delta)\ny = np.arange(-2.0, 2.0, delta)\nX, Y = np.meshgrid(x, y)\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\nZ = (Z1 - Z2) * 2"}]},{"title":"Make contour labels with custom level formatters","body":["Make contour labels with custom level formatters","We will now create contour labels with custom level formatters. This will allow us to format the labels in a specific way. In this case, we will remove trailing zeros and add a percent sign."],"code":[{"lang":"python","text":"def fmt(x):\n    s = f\"{x:.1f}\"\n    if s.endswith(\"0\"):\n        s = f\"{x:.0f}\"\n    return rf\"{s} \\%\" if plt.rcParams[\"text.usetex\"] else f\"{s} %\"\n\nfig, ax = plt.subplots()\nCS = ax.contour(X, Y, Z)\nax.clabel(CS, CS.levels, inline=True, fmt=fmt, fontsize=10)"}]},{"title":"Label contours with arbitrary strings using a dictionary","body":["Label contours with arbitrary strings using a dictionary","We can also label contours with arbitrary strings using a dictionary. This will allow us to label the contours with custom labels. In this example, we will use a list of strings to label the contours."],"code":[{"lang":"python","text":"fig1, ax1 = plt.subplots()\nCS1 = ax1.contour(X, Y, Z)\n\nfmt = {}\nstrs = ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh']\nfor l, s in zip(CS1.levels, strs):\n    fmt[l] = s\n\nax1.clabel(CS1, CS1.levels[::2], inline=True, fmt=fmt, fontsize=10)"}]},{"title":"Use a Formatter","body":["We can also use a formatter to format the contour labels. This will allow us to format the labels in a specific way. In this example, we will use a LogFormatterMathtext to format the labels."],"code":[{"lang":"python","text":"fig2, ax2 = plt.subplots()\nCS2 = ax2.contour(X, Y, 100**Z, locator=plt.LogLocator())\nfmt = ticker.LogFormatterMathtext()\nfmt.create_dummy_axis()\nax2.clabel(CS2, CS2.levels, fmt=fmt)\nax2.set_title(\"$100^Z$\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig2, ax2 = plt.subplots()\nCS2 = ax2.contour(X, Y, 100**Z, locator=plt.LogLocator())\nfmt = ticker.LogFormatterMathtext()\nfmt.create_dummy_axis()\nax2.clabel(CS2, CS2.levels, fmt=fmt)\nax2.set_title(\"$100^Z$\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-contour-line-visualization":{"intro":"This lab will guide you on how to display your own contour lines and polygons using ContourSet in Matplotlib. Contour lines for each level are a list/tuple of polygons. Filled contours between two levels are also a list/tuple of polygons. Points can be ordered clockwise or anticlockwise.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","The first step is to import the necessary libraries. In this lab, we will be using Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.cm as cm\nfrom matplotlib.contour import ContourSet\nfrom matplotlib.path import Path"}]},{"title":"Define the contour lines and polygons","body":["Define the contour lines and polygons","The next step is to define the contour lines and polygons. In this example, we have lines and filled contours between two levels."],"code":[{"lang":"python","text":"# Contour lines for each level are a list/tuple of polygons.\nlines0 = [[[0, 0], [0, 4]]]\nlines1 = [[[2, 0], [1, 2], [1, 3]]]\nlines2 = [[[3, 0], [3, 2]], [[3, 3], [3, 4]]]  # Note two lines.\n\n# Filled contours between two levels are also a list/tuple of polygons.\n# Points can be ordered clockwise or anticlockwise.\nfilled01 = [[[0, 0], [0, 4], [1, 3], [1, 2], [2, 0]]]\nfilled12 = [[[2, 0], [3, 0], [3, 2], [1, 3], [1, 2]],   # Note two polygons.\n            [[1, 4], [3, 4], [3, 3]]]"}]},{"title":"Create the plot","body":["The next step is to create the plot. This can be done using the ContourSet function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\n# Filled contours using filled=True.\ncs = ContourSet(ax, [0, 1, 2], [filled01, filled12], filled=True, cmap=cm.bone)\ncbar = fig.colorbar(cs)\n\n# Contour lines (non-filled).\nlines = ContourSet(\n    ax, [0, 1, 2], [lines0, lines1, lines2], cmap=cm.cool, linewidths=3)\ncbar.add_lines(lines)\n\nax.set(xlim=(-0.5, 3.5), ylim=(-0.5, 4.5),\n       title='User-specified contours')"}]},{"title":"Create filled contours with holes","body":["Create filled contours with holes","Multiple filled contour lines can be specified in a single list of polygon vertices along with a list of vertex kinds (code types) as described in the Path class. This is particularly useful for polygons with holes."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfilled01 = [[[0, 0], [3, 0], [3, 3], [0, 3], [1, 1], [1, 2], [2, 2], [2, 1]]]\nM = Path.MOVETO\nL = Path.LINETO\nkinds01 = [[M, L, L, L, M, L, L, L]]\ncs = ContourSet(ax, [0, 1], [filled01], [kinds01], filled=True)\ncbar = fig.colorbar(cs)\n\nax.set(xlim=(-0.5, 3.5), ylim=(-0.5, 3.5),\n       title='User specified filled contours with holes')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nfilled01 = [[[0, 0], [3, 0], [3, 3], [0, 3], [1, 1], [1, 2], [2, 2], [2, 1]]]\nM = Path.MOVETO\nL = Path.LINETO\nkinds01 = [[M, L, L, L, M, L, L, L]]\ncs = ContourSet(ax, [0, 1], [filled01], [kinds01], filled=True)\ncbar = fig.colorbar(cs)\n\nax.set(xlim=(-0.5, 3.5), ylim=(-0.5, 3.5),\n       title='User specified filled contours with holes')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-3d-contour-visualizations":{"intro":"In this lab, we will learn how to create a 3D contour plot using Matplotlib library in Python. A contour plot is a graphical representation of a 3D surface in which contours are plotted on a 2D plane. Contour plots are useful to visualize the variation of a variable with respect to two other variables.","steps":[{"title":"Import Libraries","body":["We will begin by importing the necessary libraries for creating the 3D contour plot. We will be using the matplotlib and mpl_toolkits libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cm\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Create Figure and Subplot","body":["Next, we create a figure and subplot to hold our 3D contour plot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(111, projection='3d')"}]},{"title":"Get Test Data","body":["We will use the axes3d.get_test_data() function to get some test data to plot."],"code":[{"lang":"python","text":"X, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Create Contour Plot","body":["Now we can create a 3D contour plot of the test data using the ax.contour() function."],"code":[{"lang":"python","text":"ax.contour(X, Y, Z, cmap=cm.coolwarm)"}]},{"title":"Customize Plot","body":["We can customize the plot by adding labels to the axes and adjusting the viewing angle."],"code":[{"lang":"python","text":"ax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\nax.set_zlabel('Z Label')\nax.view_init(elev=30, azim=120)"}]},{"title":"Show Plot","body":["Finally, we use the plt.show() function to display the 3D contour plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-3d-contour-plotting-with-matplotlib":{"intro":"This tutorial will guide you through the process of creating a 3D contour plot using Matplotlib in Python. The contour plot represents a 3D surface using contours or level curves. We will use the contour() function to create these level curves, and the extend3d=True option to extend the curves vertically into 'ribbons'.","steps":[{"title":"Import Libraries","body":["We need to start by importing the necessary libraries for this tutorial. We will use matplotlib.pyplot for plotting, matplotlib.cm for color maps, and mpl_toolkits.mplot3d for 3D plotting."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cm\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Create Data","body":["Next, we need to create the data we will use to generate the contour plot. We will use the get_test_data() function from the mpl_toolkits.mplot3d module to generate sample data."],"code":[{"lang":"python","text":"X, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Create 3D Axes","body":["We will use the add_subplot() function to create a 3D subplot for our plot. We will also set the projection to '3d'."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Create Contour Plot","body":["We will now create the contour plot using the contour() function. We will pass in the X, Y, and Z data, and set extend3d=True to extend the curves vertically into 'ribbons'. We will also set the colormap to cm.coolwarm for a nice color scheme."],"code":[{"lang":"python","text":"ax.contour(X, Y, Z, extend3d=True, cmap=cm.coolwarm)"}]},{"title":"Display the Plot","body":["Finally, we will use the show() function to display our plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-3d-surface-and-contour-plotting":{"intro":"This lab demonstrates how to create a 3D surface plot and project contour 'profiles' onto the walls of the graph using Matplotlib.","steps":[{"title":"Import necessary libraries","body":["In this step, we will import the necessary libraries for creating the 3D surface plot and projecting contour profiles."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Create 3D figure and data","body":["In this step, we will create a 3D figure and get test data for the surface plot."],"code":[{"lang":"python","text":"# Create a 3D figure\nfig = plt.figure()\nax = fig.add_subplot(projection='3d')\n\n# Get test data for the surface plot\nX, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Plot the 3D surface","body":["In this step, we will plot the 3D surface with the test data and customize the appearance of the plot."],"code":[{"lang":"python","text":"# Plot the 3D surface\nax.plot_surface(X, Y, Z, edgecolor='royalblue', lw=0.5, rstride=8, cstride=8, alpha=0.3)\n\n# Customize the appearance of the plot\nax.set(xlim=(-40, 40), ylim=(-40, 40), zlim=(-100, 100), xlabel='X', ylabel='Y', zlabel='Z')"}]},{"title":"Project contour profiles onto the walls of the graph","body":["Project contour profiles onto the walls of the graph","In this step, we will project contour profiles onto the walls of the graph by plotting the contours for each dimension with appropriate offsets."],"code":[{"lang":"python","text":"# Plot projections of the contours for each dimension\nax.contour(X, Y, Z, zdir='z', offset=-100, cmap='coolwarm')\nax.contour(X, Y, Z, zdir='x', offset=-40, cmap='coolwarm')\nax.contour(X, Y, Z, zdir='y', offset=40, cmap='coolwarm')"}]},{"title":"Display the plot","body":["In this step, we will display the 3D surface plot with projected contour profiles."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-filled-contour-plots-with-matplotlib":{"intro":"In this tutorial, we will learn how to create filled contour plots using the contourf method in the Matplotlib library. We will cover how to create filled contours with automatic and explicit levels, and how to set the colormap and extend settings.","steps":[{"title":"Import Libraries and Create Data","body":["Import Libraries and Create Data","First, we need to import the necessary libraries and create some data to plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Create data\norigin = 'lower'\ndelta = 0.025\nx = y = np.arange(-3.0, 3.01, delta)\nX, Y = np.meshgrid(x, y)\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\nZ = (Z1 - Z2) * 2"}]},{"title":"Create Filled Contour with Automatic Levels","body":["Create Filled Contour with Automatic Levels","Next, we will create a filled contour plot with automatic levels. We will use the contourf method with the cmap parameter set to plt.cm.bone to specify the colormap. We will also add contour lines with the contour method and pass in a subset of the contour levels used for the filled contours."],"code":[{"lang":"python","text":"# Create filled contour with automatic levels\nfig, ax = plt.subplots()\nCS = ax.contourf(X, Y, Z, 10, cmap=plt.cm.bone, origin=origin)\nCS2 = ax.contour(CS, levels=CS.levels[::2], colors='r', origin=origin)\n\n# Add title, axis labels, and colorbar\nax.set_title('Filled Contour with Automatic Levels')\nax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\ncbar = fig.colorbar(CS)\ncbar.ax.set_ylabel('Z Label')\ncbar.add_lines(CS2)\n\n# Show plot\nplt.show()"}]},{"title":"Create Filled Contour with Explicit Levels","body":["Create Filled Contour with Explicit Levels","Now, we will create a filled contour plot with explicit levels. We will use the contourf method with the levels parameter set to a list of values to specify the contour levels. We will also set the colormap to a list of colors and set the extend parameter to 'both' to show values outside the range of levels."],"code":[{"lang":"python","text":"# Create filled contour with explicit levels\nfig, ax = plt.subplots()\nlevels = [-1.5, -1, -0.5, 0, 0.5, 1]\nCS = ax.contourf(X, Y, Z, levels, colors=('r', 'g', 'b'),\n                 origin=origin, extend='both')\nCS2 = ax.contour(X, Y, Z, levels, colors=('k',),\n                 linewidths=(3,), origin=origin)\n\n# Add title, axis labels, and colorbar\nax.set_title('Filled Contour with Explicit Levels')\nax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\ncbar = fig.colorbar(CS)\ncbar.ax.set_ylabel('Z Label')\n\n# Show plot\nplt.show()"}]},{"title":"Set Colormap and Extend Settings","body":["Set Colormap and Extend Settings","Finally, we will set the colormap and extend settings. We will use the with_extremes method to set the colors for values below and above the range of levels. We will also create four subplots to show the four possible extend settings: 'neither', 'both', 'min', and 'max'."],"code":[{"lang":"python","text":"# Set colormap and extend settings\nextends = [\"neither\", \"both\", \"min\", \"max\"]\ncmap = plt.colormaps[\"winter\"].with_extremes(under=\"magenta\", over=\"yellow\")\n\n# Create subplots with different extend settings\nfig, axs = plt.subplots(2, 2, layout=\"constrained\")\nfor ax, extend in zip(axs.flat, extends):\n    cs = ax.contourf(X, Y, Z, levels, cmap=cmap, extend=extend, origin=origin)\n    fig.colorbar(cs, ax=ax, shrink=0.9)\n    ax.set_title(\"extend = %s\" % extend)\n    ax.locator_params(nbins=4)\n\n# Show plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Set colormap and extend settings\nextends = [\"neither\", \"both\", \"min\", \"max\"]\ncmap = plt.colormaps[\"winter\"].with_extremes(under=\"magenta\", over=\"yellow\")\n\n# Create subplots with different extend settings\nfig, axs = plt.subplots(2, 2, layout=\"constrained\")\nfor ax, extend in zip(axs.flat, extends):\n    cs = ax.contourf(X, Y, Z, levels, cmap=cmap, extend=extend, origin=origin)\n    fig.colorbar(cs, ax=ax, shrink=0.9)\n    ax.set_title(\"extend = %s\" % extend)\n    ax.locator_params(nbins=4)\n\n# Show plot\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-filled-contour-plots-with-hatching":{"intro":"In this lab, we will learn how to create filled contour plots with hatched patterns using Python's Matplotlib library. Contour plots are used to display three-dimensional data in two dimensions. They are particularly useful for visualizing data that has peaks and valleys, such as topographical data.","steps":[{"title":"Import Libraries","body":["We begin by importing the necessary libraries. In this lab, we will be using NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we will create some sample data to plot. In this example, we will create a 2D grid of x and y values and use them to calculate z values."],"code":[{"lang":"python","text":"# invent some numbers, turning the x and y arrays into simple\n# 2d arrays, which make combining them together easier.\nx = np.linspace(-3, 5, 150).reshape(1, -1)\ny = np.linspace(-3, 5, 120).reshape(-1, 1)\nz = np.cos(x) + np.sin(y)"}]},{"title":"Simplest Hatched Plot with a Colorbar","body":["Simplest Hatched Plot with a Colorbar","In this step, we will create the simplest hatched plot with a colorbar. We will use the contourf function to create the filled contour plot and specify the hatches using the hatches parameter."],"code":[{"lang":"python","text":"fig1, ax1 = plt.subplots()\ncs = ax1.contourf(x, y, z, hatches=['-', '/', '\\\\', '//'],\n                  cmap='gray', extend='both', alpha=0.5)\nfig1.colorbar(cs)"}]},{"title":"Plot of Hatches without Color with a Legend","body":["Plot of Hatches without Color with a Legend","In this step, we will create a plot of hatches without color and add a legend. We will use the contour function to create the contour lines and the contourf function to specify the hatches without color."],"code":[{"lang":"python","text":"fig2, ax2 = plt.subplots()\nn_levels = 6\nax2.contour(x, y, z, n_levels, colors='black', linestyles='-')\ncs = ax2.contourf(x, y, z, n_levels, colors='none',\n                  hatches=['.', '/', '\\\\', None, '\\\\\\\\', '*'],\n                  extend='lower')\n\n# create a legend for the contour set\nartists, labels = cs.legend_elements(str_format='{:2.1f}'.format)\nax2.legend(artists, labels, handleheight=2, framealpha=1)"}]},{"title":"Display the Plots","body":["Finally, we will display the plots using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-contourf-and-log-color-scale":{"intro":"In this lab, we will learn how to use the contourf function in Matplotlib to create filled contour plots with a logarithmic color scale. We will use a dataset with positive and negative values to demonstrate this feature.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We need to import the following libraries:","• matplotlib.pyplot for creating plots and visualizations • numpy for generating the dataset"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate the dataset","body":["We will generate a dataset with positive and negative values using numpy:"],"code":[{"lang":"python","text":"N = 100\nx = np.linspace(-3.0, 3.0, N)\ny = np.linspace(-2.0, 2.0, N)\n\nX, Y = np.meshgrid(x, y)\n\n# A low hump with a spike coming out.\n# Needs to have z/colour axis on a log scale, so we see both hump and spike.\n# A linear scale only shows the spike.\nZ1 = np.exp(-X**2 - Y**2)\nZ2 = np.exp(-(X * 10)**2 - (Y * 10)**2)\nz = Z1 + 50 * Z2\n\n# Put in some negative values (lower left corner) to cause trouble with logs:\nz[:5, :5] = -1\n\n# The following is not strictly essential, but it will eliminate\n# a warning.  Comment it out to see the warning.\nz = ma.masked_where(z <= 0, z)"}]},{"title":"Create the plot","body":["We will use the contourf function to create a filled contour plot with a logarithmic color scale:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ncs = ax.contourf(X, Y, z, locator=ticker.LogLocator(), cmap=cm.PuBu_r)\n\ncbar = fig.colorbar(cs)\n\nplt.show()"}]},{"title":"Customize the plot","body":["We can customize the plot by adding labels, titles, and changing the color map:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ncs = ax.contourf(X, Y, z, locator=ticker.LogLocator(), cmap=cm.coolwarm)\n\nax.set_title('Contourf Plot with Log Color Scale')\nax.set_xlabel('X-axis')\nax.set_ylabel('Y-axis')\n\ncbar = fig.colorbar(cs)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\ncs = ax.contourf(X, Y, z, locator=ticker.LogLocator(), cmap=cm.coolwarm)\n\nax.set_title('Contourf Plot with Log Color Scale')\nax.set_xlabel('X-axis')\nax.set_ylabel('Y-axis')\n\ncbar = fig.colorbar(cs)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-3d-contour-plots-with-matplotlib":{"intro":"In this lab, you will learn how to create a 3D contour plot using Matplotlib in Python. A contour plot is a graphical representation of the relationship between three variables. It is used to display the relationship between two variables on the x and y axes and the third variable on the z-axis. Contour plots are widely used in scientific and engineering fields to display data in a 3D space.","steps":[{"title":"Import the Required Libraries","body":["Before we get started, we need to import the required libraries. We will be using Matplotlib and Axes3D from mpl_toolkits.mplot3d."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Create the Figure and Axes Objects","body":["Create the Figure and Axes Objects","We will now create the figure and axes objects using the add_subplot() method. We will set the projection parameter to '3d' to create a 3D plot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(111, projection='3d')"}]},{"title":"Generate the Data","body":["We will now generate the data to be used in the 3D contour plot. We will use the axes3d.get_test_data() method to generate the data. This method generates test data for a 3D plot."],"code":[{"lang":"python","text":"X, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Create the Contour Plot","body":["We will now create the contour plot using the contourf() method. This method creates filled contours. We will set the cmap parameter to cm.coolwarm to use the cool-warm color map."],"code":[{"lang":"python","text":"ax.contourf(X, Y, Z, cmap=cm.coolwarm)"}]},{"title":"Display the Plot","body":["We will now display the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-projecting-filled-contour-onto-a-3d-graph":{"intro":"This lab will guide you through the process of creating a 3D surface graph with filled contour profiles projected onto the walls of the graph. This is a useful visualization technique for understanding complex 3D data. We will be using Python's Matplotlib library to create the graph.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Create 3D Axes","body":["Next, we will create a 3D axis object using the add_subplot method."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Create Data","body":["We will use the axes3d.get_test_data method to create sample data for our graph."],"code":[{"lang":"python","text":"X, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Plot the 3D Surface","body":["We will plot the 3D surface using the plot_surface method. We will also set some parameters such as edgecolor, linewidth, and alpha."],"code":[{"lang":"python","text":"ax.plot_surface(X, Y, Z, edgecolor='royalblue', lw=0.5, rstride=8, cstride=8, alpha=0.3)"}]},{"title":"Project Contour Profiles","body":["We will now project the contour profiles onto the walls of the graph. This is done using the contourf method. We will set the zdir parameter to 'z', 'x', and 'y' to project the contour profiles onto the z, x, and y walls respectively. We will also set the offset parameter to match the appropriate axes limits."],"code":[{"lang":"python","text":"ax.contourf(X, Y, Z, zdir='z', offset=-100, cmap='coolwarm')\nax.contourf(X, Y, Z, zdir='x', offset=-40, cmap='coolwarm')\nax.contourf(X, Y, Z, zdir='y', offset=40, cmap='coolwarm')"}]},{"title":"Set Graph Limits and Labels","body":["Finally, we will set the limits and labels for the graph axes."],"code":[{"lang":"python","text":"ax.set(xlim=(-40, 40), ylim=(-40, 40), zlim=(-100, 100), xlabel='X', ylabel='Y', zlabel='Z')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.set(xlim=(-40, 40), ylim=(-40, 40), zlim=(-100, 100), xlabel='X', ylabel='Y', zlabel='Z')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-optimization-contour-plotting-with-matplotli":{"intro":"This lab will guide you through the process of creating a contour plot using Matplotlib in Python. You will learn how to generate curves with larger values and how to use ~matplotlib.patheffects.TickedStroke to distinguish between the valid and invalid sides of the constraint boundaries.","steps":[{"title":"Import the Required Libraries","body":["To get started, you need to import the necessary libraries. Matplotlib and NumPy are required to create the contour plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib import patheffects"}]},{"title":"Set Up the Survey Vectors and Matrices","body":["Set Up the Survey Vectors and Matrices","Next, set up the survey vectors and matrices. Design disk loading and gear ratio."],"code":[{"lang":"python","text":"nx = 101\nny = 105\n\n# Set up survey vectors\nxvec = np.linspace(0.001, 4.0, nx)\nyvec = np.linspace(0.001, 4.0, ny)\n\n# Set up survey matrices.  Design disk loading and gear ratio.\nx1, x2 = np.meshgrid(xvec, yvec)"}]},{"title":"Evaluate the Data to Plot","body":["Now, evaluate some data to plot. In this example, we will plot an objective function, g1, g2, and g3."],"code":[{"lang":"python","text":"# Evaluate some stuff to plot\nobj = x1**2 + x2**2 - 2*x1 - 2*x2 + 2\ng1 = -(3*x1 + x2 - 5.5)\ng2 = -(x1 + 2*x2 - 4.5)\ng3 = 0.8 + x1**-3 - x2"}]},{"title":"Create the Contour Plot","body":["Now, create the contour plot using the ax.contour() method. This method is used to represent the topography of the objective function and generate boundary curves of the constraint functions."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(6, 6))\n\ncntr = ax.contour(x1, x2, obj, [0.01, 0.1, 0.5, 1, 2, 4, 8, 16], colors='black')\nax.clabel(cntr, fmt=\"%2.1f\", use_clabeltext=True)\n\ncg1 = ax.contour(x1, x2, g1, [0], colors='sandybrown')\nplt.setp(cg1.collections, path_effects=[patheffects.withTickedStroke(angle=135)])\n\ncg2 = ax.contour(x1, x2, g2, [0], colors='orangered')\nplt.setp(cg2.collections, path_effects=[patheffects.withTickedStroke(angle=60, length=2)])\n\ncg3 = ax.contour(x1, x2, g3, [0], colors='mediumblue')\nplt.setp(cg3.collections, path_effects=[patheffects.withTickedStroke(spacing=7)])\n\nax.set_xlim(0, 4)\nax.set_ylim(0, 4)\n\nplt.show()"}]},{"title":"Interpret the Results","body":["The resulting plot shows the topography of the objective function and the boundary curves of the constraint functions. The ~matplotlib.patheffects.TickedStroke is used to distinguish between the valid and invalid sides of the constraint boundaries."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-mouse-interaction-with-matplotlib-plot":{"intro":"This lab demonstrates an example of how to interact with the plotting canvas by connecting to move and click events using Matplotlib library in Python. Matplotlib is a data visualization library that allows users to create static, animated, and interactive visualizations in Python.","steps":[{"title":"Creating a Sine Wave Plot","body":["First, we need to create a sine wave plot using numpy and matplotlib libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nt = np.arange(0.0, 1.0, 0.01)\ns = np.sin(2 * np.pi * t)\nfig, ax = plt.subplots()\nax.plot(t, s)"}]},{"title":"Mouse Move Event","body":["We can connect to mouse move events using the motion_notify_event method. In this example, we are printing the x and y data coordinates and x and y pixel coordinates when the mouse moves over the plot."],"code":[{"lang":"python","text":"def on_move(event):\n    if event.inaxes:\n        print(f'data coords {event.xdata} {event.ydata},',\n              f'pixel coords {event.x} {event.y}')\n\nbinding_id = plt.connect('motion_notify_event', on_move)"}]},{"title":"Mouse Click Event","body":[],"code":[{"lang":"python","text":"from matplotlib.backend_bases import MouseButton\n\ndef on_click(event):\n    if event.button is MouseButton.LEFT:\n        print('disconnecting callback')\n        plt.disconnect(binding_id)\n\nplt.connect('button_press_event', on_click)"}]},{"title":"Displaying the Plot","body":["Finally, we need to display the plot using the show method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-python-matplotlib-scatter-plot-creation":{"intro":"This step-by-step lab will guide you through using Python's Matplotlib library to create visualizations. Matplotlib is a data visualization library that allows users to create a wide range of visualizations, including line plots, scatter plots, and histograms. In this lab, we will create a simple scatter plot using Matplotlib.","steps":[{"title":"Import libraries","body":["Before we start creating our visualization, we need to import the necessary libraries. In this example, we will be using numpy and matplotlib.pyplot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create data","body":["Next, we will create some random data to use in our visualization. In this example, we will create two arrays of random data using numpy."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nx = np.random.rand(20)\ny = 1e7 * np.random.rand(20)"}]},{"title":"Create the plot","body":["Now that we have our data, we can create our plot using Matplotlib. In this example, we will create a scatter plot using the plot() function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nplt.plot(x, y, 'o')"}]},{"title":"Format the plot","body":["To make our plot more readable, we can format it using Matplotlib's formatting functions. In this example, we will format the y-axis labels to display values in millions."],"code":[{"lang":"python","text":"def millions(x):\n    return '$%1.1fM' % (x * 1e-6)\n\nax.fmt_ydata = millions"}]},{"title":"Display the plot","body":["Finally, we can display our plot using Matplotlib's show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-compute-cross-spectral-density-in-python":{"intro":"In signal processing, Cross Spectral Density (CSD) is a measure of the correlation between two signals in the frequency domain. It is used to determine how much two signals are related to each other in terms of their frequency content. In this lab, you will learn how to compute the CSD of two signals using Python's Matplotlib library.","steps":[{"title":"Import Required Libraries","body":["We need to import the following libraries: numpy and matplotlib.pyplot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Signals","body":["We need to generate two signals. These signals contain a coherent part and a random part. The coherent part of both signals has a frequency of 10 Hz. The random part of the signals is generated using white noise that is passed through a low-pass filter to create colored noise."],"code":[{"lang":"python","text":"dt = 0.01\nt = np.arange(0, 30, dt)\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nnse1 = np.random.randn(len(t))                 # white noise 1\nnse2 = np.random.randn(len(t))                 # white noise 2\nr = np.exp(-t / 0.05)\n\ncnse1 = np.convolve(nse1, r, mode='same') * dt   # colored noise 1\ncnse2 = np.convolve(nse2, r, mode='same') * dt   # colored noise 2\n\n# two signals with a coherent part and a random part\ns1 = 0.01 * np.sin(2 * np.pi * 10 * t) + cnse1\ns2 = 0.01 * np.sin(2 * np.pi * 10 * t) + cnse2"}]},{"title":"Plot Signals","body":["We can plot the two generated signals using Matplotlib's plot function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(t, s1, label='s1')\nax.plot(t, s2, label='s2')\nax.set_xlabel('Time')\nax.set_ylabel('Amplitude')\nax.legend()\nplt.show()"}]},{"title":"Compute CSD","body":["To compute the CSD of two signals, we need to use Matplotlib's csd function. The function takes the two signals, the number of points for the FFT, and the sampling frequency as inputs."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\ncxy, f = ax.csd(s1, s2, 256, 1. / dt)\nax.set_ylabel('CSD (dB)')\nplt.show()"}]},{"title":"Interpret Results","body":["The resulting plot shows the CSD of the two signals. The x-axis represents the frequency and the y-axis represents the strength of the correlation between the two signals at that frequency. The plot shows a peak at 10 Hz, which is the frequency of the coherent part of the signals. This indicates that the two signals are strongly correlated at this frequency."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-interactive-data-exploration-with-matplotlib":{"intro":"The matplotlib.widgets.Cursor is a useful tool for exploring the data plotted on a Matplotlib graph. It allows you to interactively display the x and y values of the data point under the cursor.","steps":[{"title":"Import Required Libraries","body":["In this step, we import the required libraries: matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["In this step, we generate random data points using numpy."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# Generate random data points\nx, y = 4*(np.random.rand(2, 100) - .5)"}]},{"title":"Create a Figure and Axes","body":["In this step, we create a figure and axes object using plt.subplots."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(8, 6))"}]},{"title":"Plot Data Points","body":["In this step, we plot the generated data points on the axes object."],"code":[{"lang":"python","text":"ax.plot(x, y, 'o')\nax.set_xlim(-2, 2)\nax.set_ylim(-2, 2)"}]},{"title":"Create a Cursor","body":["In this step, we create a cursor object using Cursor class and pass the axes object as an argument. We also specify the cursor color and line width."],"code":[{"lang":"python","text":"cursor = Cursor(ax, useblit=True, color='red', linewidth=2)"}]},{"title":"Display the Plot","body":["In this step, we display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-crosshair-cursor":{"intro":"Matplotlib is a popular data visualization library that provides a wide range of tools for creating visualizations in Python. One of the interesting features of Matplotlib is the ability to add a crosshair cursor to a plot. In this lab, you will learn how to add a crosshair cursor to a Matplotlib plot.","steps":[{"title":"Simple Cursor","body":["The first step is to add a simple cursor to a Matplotlib plot. This cursor will display the x and y values of the current mouse location."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.backend_bases import MouseEvent\n\nclass Cursor:\n    \"\"\"\n    A cross hair cursor.\n    \"\"\"\n    def __init__(self, ax):\n        self.ax = ax\n        self.horizontal_line = ax.axhline(color='k', lw=0.8, ls='--')\n        self.vertical_line = ax.axvline(color='k', lw=0.8, ls='--')\n        # text location in axes coordinates\n        self.text = ax.text(0.72, 0.9, '', transform=ax.transAxes)\n\n    def set_cross_hair_visible(self, visible):\n        need_redraw = self.horizontal_line.get_visible() != visible\n        self.horizontal_line.set_visible(visible)\n        self.vertical_line.set_visible(visible)\n        self.text.set_visible(visible)\n        return need_redraw\n\n    def on_mouse_move(self, event):\n        if not event.inaxes:\n            need_redraw = self.set_cross_hair_visible(False)\n            if need_redraw:\n                self.ax.figure.canvas.draw()\n        else:\n            self.set_cross_hair_visible(True)\n            x, y = event.xdata, event.ydata\n            # update the line positions\n            self.horizontal_line.set_ydata([y])\n            self.vertical_line.set_xdata([x])\n            self.text.set_text(f'x={x:1.2f}, y={y:1.2f}')\n            self.ax.figure.canvas.draw()\n\nx = np.arange(0, 1, 0.01)\ny = np.sin(2 * 2 * np.pi * x)\n\nfig, ax = plt.subplots()\nax.set_title('Simple cursor')\nax.plot(x, y, 'o')\ncursor = Cursor(ax)\nfig.canvas.mpl_connect('motion_notify_event', cursor.on_mouse_move)\n\nplt.show()"}]},{"title":"Faster Cursoring using Blitting","body":["Faster Cursoring using Blitting","The cursor created in the previous step is a bit slow because it redraws the figure on every mouse move. In this step, we will create a cursor that uses blitting for faster rendering."],"code":[{"lang":"python","text":"class BlittedCursor:\n    \"\"\"\n    A cross-hair cursor using blitting for faster redraw.\n    \"\"\"\n    def __init__(self, ax):\n        self.ax = ax\n        self.background = None\n        self.horizontal_line = ax.axhline(color='k', lw=0.8, ls='--')\n        self.vertical_line = ax.axvline(color='k', lw=0.8, ls='--')\n        # text location in axes coordinates\n        self.text = ax.text(0.72, 0.9, '', transform=ax.transAxes)\n        self._creating_background = False\n        ax.figure.canvas.mpl_connect('draw_event', self.on_draw)\n\n    def on_draw(self, event):\n        self.create_new_background()\n\n    def set_cross_hair_visible(self, visible):\n        need_redraw = self.horizontal_line.get_visible() != visible\n        self.horizontal_line.set_visible(visible)\n        self.vertical_line.set_visible(visible)\n        self.text.set_visible(visible)\n        return need_redraw\n\n    def create_new_background(self):\n        if self._creating_background:\n            # discard calls triggered from within this function\n            return\n        self._creating_background = True\n        self.set_cross_hair_visible(False)\n        self.ax.figure.canvas.draw()\n        self.background = self.ax.figure.canvas.copy_from_bbox(self.ax.bbox)\n        self.set_cross_hair_visible(True)\n        self._creating_background = False\n\n    def on_mouse_move(self, event):\n        if self.background is None:\n            self.create_new_background()\n        if not event.inaxes:\n            need_redraw = self.set_cross_hair_visible(False)\n            if need_redraw:\n                self.ax.figure.canvas.restore_region(self.background)\n                self.ax.figure.canvas.blit(self.ax.bbox)\n        else:\n            self.set_cross_hair_visible(True)\n            # update the line positions\n            x, y = event.xdata, event.ydata\n            self.horizontal_line.set_ydata([y])"}]},{"title":"Snapping to Data Points","body":["The cursor created in the previous step is still a bit slow because it updates the cursor position on every mouse move. In this step, we will create a cursor that snaps to the data points of a Line2D object."],"code":[{"lang":"python","text":"class SnappingCursor:\n    \"\"\"\n    A cross-hair cursor that snaps to the data point of a line, which is\n    closest to the *x* position of the cursor.\n\n    For simplicity, this assumes that *x* values of the data are sorted.\n    \"\"\"\n    def __init__(self, ax, line):\n        self.ax = ax\n        self.horizontal_line = ax.axhline(color='k', lw=0.8, ls='--')\n        self.vertical_line = ax.axvline(color='k', lw=0.8, ls='--')\n        self.x, self.y = line.get_data()\n        self._last_index = None\n        # text location in axes coords\n        self.text = ax.text(0.72, 0.9, '', transform=ax.transAxes)\n\n    def set_cross_hair_visible(self, visible):\n        need_redraw = self.horizontal_line.get_visible() != visible\n        self.horizontal_line.set_visible(visible)\n        self.vertical_line.set_visible(visible)\n        self.text.set_visible(visible)\n        return need_redraw\n\n    def on_mouse_move(self, event):\n        if not event.inaxes:\n            self._last_index = None\n            need_redraw = self.set_cross_hair_visible(False)\n            if need_redraw:\n                self.ax.figure.canvas.draw()\n        else:\n            self.set_cross_hair_visible(True)\n            x, y = event.xdata, event.ydata\n            index = min(np.searchsorted(self.x, x), len(self.x) - 1)\n            if index == self._last_index:\n                return  # still on the same data point. Nothing to do.\n            self._last_index = index\n            x = self.x[index]\n            y = self.y[index]\n            # update the line positions\n            self.horizontal_line.set_ydata([y])\n            self.vertical_line.set_xdata([x])\n            self.text.set_text(f'x={x:1.2f}, y={y:1.2f}')\n            self.ax.figure.canvas.draw()\n\nx = np.arange(0, 1, 0.01)\ny = np.sin(2 * 2 * np.pi * x)\n\nfig, ax = plt.subplots()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"class SnappingCursor:\n    \"\"\"\n    A cross-hair cursor that snaps to the data point of a line, which is\n    closest to the *x* position of the cursor.\n\n    For simplicity, this assumes that *x* values of the data are sorted.\n    \"\"\"\n    def __init__(self, ax, line):\n        self.ax = ax\n        self.horizontal_line = ax.axhline(color='k', lw=0.8, ls='--')\n        self.vertical_line = ax.axvline(color='k', lw=0.8, ls='--')\n        self.x, self.y = line.get_data()\n        self._last_index = None\n        # text location in axes coords\n        self.text = ax.text(0.72, 0.9, '', transform=ax.transAxes)\n\n    def set_cross_hair_visible(self, visible):\n        need_redraw = self.horizontal_line.get_visible() != visible\n        self.horizontal_line.set_visible(visible)\n        self.vertical_line.set_visible(visible)\n        self.text.set_visible(visible)\n        return need_redraw\n\n    def on_mouse_move(self, event):\n        if not event.inaxes:\n            self._last_index = None\n            need_redraw = self.set_cross_hair_visible(False)\n            if need_redraw:\n                self.ax.figure.canvas.draw()\n        else:\n            self.set_cross_hair_visible(True)\n            x, y = event.xdata, event.ydata\n            index = min(np.searchsorted(self.x, x), len(self.x) - 1)\n            if index == self._last_index:\n                return  # still on the same data point. Nothing to do.\n            self._last_index = index\n            x = self.x[index]\n            y = self.y[index]\n            # update the line positions\n            self.horizontal_line.set_ydata([y])\n            self.vertical_line.set_xdata([x])\n            self.text.set_text(f'x={x:1.2f}, y={y:1.2f}')\n            self.ax.figure.canvas.draw()\n\nx = np.arange(0, 1, 0.01)\ny = np.sin(2 * 2 * np.pi * x)\n\nfig, ax = plt.subplots()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-drawing-a-curve-with-error-band":{"intro":"This tutorial will guide you on how to draw a curve with an error band using Python Matplotlib. An error band is used to indicate the uncertainty of the curve. In this example, we assume that the error can be given as a scalar _err_ that describes the uncertainty perpendicular to the curve in every point. We visualize this error as a colored band around the path using a .PathPatch. The patch is created from two path segments _(xp, yp)_, and _(xn, yn)_ that are shifted by +/- _err_ perpendicular to the curve _(x, y)_.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. We will be using Matplotlib, NumPy, PathPatch, and Path."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.patches import PathPatch\nfrom matplotlib.path import Path"}]},{"title":"Define the Curve","body":["Next, we define the curve that we want to draw the error band around. In this example, we will be using a parametrized curve. A parametrized curve x(t), y(t) can directly be drawn using ~.Axes.plot."],"code":[{"lang":"python","text":"N = 400\nt = np.linspace(0, 2 * np.pi, N)\nr = 0.5 + np.cos(t)\nx, y = r * np.cos(t), r * np.sin(t)"}]},{"title":"Define the Error Band","body":["We will now define the error band that we want to draw around the curve. In this example, we will be assuming that the error can be given as a scalar _err_ that describes the uncertainty perpendicular to the curve in every point."],"code":[{"lang":"python","text":"def draw_error_band(ax, x, y, err, **kwargs):\n    # Calculate normals via centered finite differences (except the first point\n    # which uses a forward difference and the last point which uses a backward\n    # difference).\n    dx = np.concatenate([[x[1] - x[0]], x[2:] - x[:-2], [x[-1] - x[-2]]])\n    dy = np.concatenate([[y[1] - y[0]], y[2:] - y[:-2], [y[-1] - y[-2]]])\n    l = np.hypot(dx, dy)\n    nx = dy / l\n    ny = -dx / l\n\n    # end points of errors\n    xp = x + nx * err\n    yp = y + ny * err\n    xn = x - nx * err\n    yn = y - ny * err\n\n    vertices = np.block([[xp, xn[::-1]],\n                         [yp, yn[::-1]]]).T\n    codes = np.full(len(vertices), Path.LINETO)\n    codes[0] = codes[len(xp)] = Path.MOVETO\n    path = Path(vertices, codes)\n    ax.add_patch(PathPatch(path, **kwargs))"}]},{"title":"Draw the Error Band","body":["We can now draw the error band by calling the draw_error_band function and passing in the appropriate parameters."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(1, 2, layout='constrained', sharex=True, sharey=True)\nerrs = [\n    (axs[0], \"constant error\", 0.05),\n    (axs[1], \"variable error\", 0.05 * np.sin(2 * t) ** 2 + 0.04),\n]\nfor i, (ax, title, err) in enumerate(errs):\n    ax.set(title=title, aspect=1, xticks=[], yticks=[])\n    ax.plot(x, y, \"k\")\n    draw_error_band(ax, x, y, err=err,\n                    facecolor=f\"C{i}\", edgecolor=\"none\", alpha=.3)\n\nplt.show()"}]},{"title":"View the Error Band","body":["The error band should now be visible around the curve."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-custom-box-styles-in-matplotlib":{"intro":"Matplotlib is a plotting library for the Python programming language and its numerical mathematics extension NumPy. One of the features of Matplotlib is the ability to create customized box styles.","steps":[{"title":"Implement a custom box style as a function","body":["Implement a custom box style as a function","Custom box styles can be implemented as functions that take arguments specifying both a rectangular box and the amount of \"mutation\", and return the \"mutated\" path. Here, we will implement a custom box style that returns a new path which adds an \"arrow\" shape on the left of the box."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.patches import BoxStyle\nfrom matplotlib.path import Path\n\ndef custom_box_style(x0, y0, width, height, mutation_size):\n    \"\"\"\n    Given the location and size of the box, return the path of the box around\n    it.\n\n    Rotation is automatically taken care of.\n\n    Parameters\n    ----------\n    x0, y0, width, height : float\n        Box location and size.\n    mutation_size : float\n        Mutation reference scale, typically the text font size.\n    \"\"\"\n    # padding\n    mypad = 0.3\n    pad = mutation_size * mypad\n    # width and height with padding added.\n    width = width + 2 * pad\n    height = height + 2 * pad\n    # boundary of the padded box\n    x0, y0 = x0 - pad, y0 - pad\n    x1, y1 = x0 + width, y0 + height\n    # return the new path\n    return Path([(x0, y0),\n                 (x1, y0), (x1, y1), (x0, y1),\n                 (x0-pad, (y0+y1)/2), (x0, y0),\n                 (x0, y0)],\n                closed=True)\n\nfig, ax = plt.subplots(figsize=(3, 3))\nax.text(0.5, 0.5, \"Test\", size=30, va=\"center\", ha=\"center\", rotation=30,\n        bbox=dict(boxstyle=custom_box_style, alpha=0.2))\nplt.show()"}]},{"title":"Implement a custom box style as a class","body":["Implement a custom box style as a class","Custom box styles can also be implemented as classes that implement __call__. The classes can then be registered into the BoxStyle._style_list dict, which allows specifying the box style as a string, bbox=dict(boxstyle=\"registered_name,param=value,...\", ...)."],"code":[{"lang":"python","text":"class MyStyle:\n    \"\"\"A simple box.\"\"\"\n\n    def __init__(self, pad=0.3):\n        \"\"\"\n        The arguments must be floats and have default values.\n\n        Parameters\n        ----------\n        pad : float\n            amount of padding\n        \"\"\"\n        self.pad = pad\n        super().__init__()\n\n    def __call__(self, x0, y0, width, height, mutation_size):\n        \"\"\"\n        Given the location and size of the box, return the path of the box\n        around it.\n\n        Rotation is automatically taken care of.\n\n        Parameters\n        ----------\n        x0, y0, width, height : float\n            Box location and size.\n        mutation_size : float\n            Reference scale for the mutation, typically the text font size.\n        \"\"\"\n        # padding\n        pad = mutation_size * self.pad\n        # width and height with padding added\n        width = width + 2.*pad\n        height = height + 2.*pad\n        # boundary of the padded box\n        x0, y0 = x0 - pad, y0 - pad\n        x1, y1 = x0 + width, y0 + height\n        # return the new path\n        return Path([(x0, y0),\n                     (x1, y0), (x1, y1), (x0, y1),\n                     (x0-pad, (y0+y1)/2.), (x0, y0),\n                     (x0, y0)],\n                    closed=True)\n\n\nBoxStyle._style_list[\"angled\"] = MyStyle  # Register the custom style.\n\nfig, ax = plt.subplots(figsize=(3, 3))"}]},{"title":"Register the custom box style with Matplotlib","body":["Register the custom box style with Matplotlib","Once you have implemented a custom box style as a class, you can register it with Matplotlib. This allows you to specify the box style as a string, bbox=dict(boxstyle=\"registered_name,param=value,...\", ...)."],"code":[{"lang":"python","text":"BoxStyle._style_list[\"angled\"] = MyStyle  # Register the custom style."}]},{"title":"Use the custom box style","body":["Once you have implemented and registered a custom box style, you can use it with Axes.text."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(3, 3))\nax.text(0.5, 0.5, \"Test\", size=30, va=\"center\", ha=\"center\", rotation=30,\n        bbox=dict(boxstyle=\"angled,pad=0.5\", alpha=0.2))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(figsize=(3, 3))\nax.text(0.5, 0.5, \"Test\", size=30, va=\"center\", ha=\"center\", rotation=30,\n        bbox=dict(boxstyle=\"angled,pad=0.5\", alpha=0.2))"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-custom-figure-subclasses":{"intro":"In this lab, you will learn how to create custom figure subclasses in Matplotlib. You will create a WatermarkFigure class that adds a text watermark to the plot.","steps":[{"title":"Import necessary libraries","body":["First, import the necessary libraries: matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a custom figure subclass","body":["Create a custom figure subclass","Create a custom figure subclass called WatermarkFigure that adds a text watermark to the plot. This class inherits from the Figure class of Matplotlib."],"code":[{"lang":"python","text":"from matplotlib.figure import Figure\n\nclass WatermarkFigure(Figure):\n    \"\"\"A figure with a text watermark.\"\"\"\n\n    def __init__(self, *args, watermark=None, **kwargs):\n        super().__init__(*args, **kwargs)\n\n        if watermark is not None:\n            bbox = dict(boxstyle='square', lw=3, ec='gray',\n                        fc=(0.9, 0.9, .9, .5), alpha=0.5)\n            self.text(0.5, 0.5, watermark,\n                      ha='center', va='center', rotation=30,\n                      fontsize=40, color='gray', alpha=0.5, bbox=bbox)"}]},{"title":"Create data for the plot","body":["Create some data for the plot. In this example, we will create x and y arrays using the numpy library."],"code":[{"lang":"python","text":"x = np.linspace(-3, 3, 201)\ny = np.tanh(x) + 0.1 * np.cos(5 * x)"}]},{"title":"Plot the data using custom figure subclass","body":["Plot the data using custom figure subclass","Use the plt.figure() function to plot the data using the custom figure subclass WatermarkFigure. In this example, we will add the watermark text \"draft\" to the plot."],"code":[{"lang":"python","text":"plt.figure(FigureClass=WatermarkFigure, watermark='draft')\nplt.plot(x, y)"}]},{"title":"Review references","body":["Review the references used in this example."],"code":[{"lang":"python","text":"# References\n# matplotlib.pyplot.figure\n# matplotlib.figure.Figure\n# matplotlib.figure.Figure.text"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# References\n# matplotlib.pyplot.figure\n# matplotlib.figure.Figure\n# matplotlib.figure.Figure.text"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-composing-custom-legends":{"intro":"The Python Matplotlib library provides a flexible way to create and customize legends in a plot. Legends are an essential component of any plot, as they provide a clear and concise explanation of the data represented in the plot. This lab will guide you through the process of composing custom legends using Matplotlib objects.","steps":[{"title":"Plotting Lines","body":["In this step, we will plot a set of lines using the Matplotlib library. First, we create some random data using NumPy. Next, we set the color cycle using the cycler function to specify the color map. Finally, we plot the data using the plot function and call legend() to generate the legend."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set random state for reproducibility\nnp.random.seed(19680801)\n\n# Create random data\nN = 10\ndata = (np.geomspace(1, 10, 100) + np.random.randn(N, 100)).T\n\n# Set color cycle\ncmap = plt.cm.coolwarm\nplt.rcParams['axes.prop_cycle'] = cycler(color=cmap(np.linspace(0, 1, N)))\n\n# Plot data and generate legend\nfig, ax = plt.subplots()\nlines = ax.plot(data)\nax.legend()"}]},{"title":"Composing Custom Legend","body":["In this step, we will create a custom legend using Matplotlib objects. First, we import the Line2D class from the matplotlib.lines module. Next, we create a list of Line2D objects with custom color, width, and label attributes. Finally, we plot the data again using the plot function and call legend() with the custom lines and corresponding labels."],"code":[{"lang":"python","text":"# Import Line2D class\nfrom matplotlib.lines import Line2D\n\n# Create custom lines\ncustom_lines = [Line2D([0], [0], color=cmap(0.), lw=4),\n                Line2D([0], [0], color=cmap(.5), lw=4),\n                Line2D([0], [0], color=cmap(1.), lw=4)]\n\n# Plot data and generate custom legend\nfig, ax = plt.subplots()\nlines = ax.plot(data)\nax.legend(custom_lines, ['Cold', 'Medium', 'Hot'])"}]},{"title":"Composing Custom Legend with Different Matplotlib Objects","body":["Composing Custom Legend with Different Matplotlib Objects","In this step, we will create a custom legend using different Matplotlib objects, including Line2D and Patch. First, we import the Patch class from the matplotlib.patches module. Next, we create a list of Line2D and Patch objects with custom attributes. Finally, we call legend() with the custom objects and corresponding labels."],"code":[{"lang":"python","text":"# Import Line2D and Patch classes\nfrom matplotlib.lines import Line2D\nfrom matplotlib.patches import Patch\n\n# Create legend elements\nlegend_elements = [Line2D([0], [0], color='b', lw=4, label='Line'),\n                   Line2D([0], [0], marker='o', color='w', label='Scatter',\n                          markerfacecolor='g', markersize=15),\n                   Patch(facecolor='orange', edgecolor='r',\n                         label='Color Patch')]\n\n# Plot data and generate custom legend\nfig, ax = plt.subplots()\nax.legend(handles=legend_elements, loc='center')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Import Line2D and Patch classes\nfrom matplotlib.lines import Line2D\nfrom matplotlib.patches import Patch\n\n# Create legend elements\nlegend_elements = [Line2D([0], [0], color='b', lw=4, label='Line'),\n                   Line2D([0], [0], marker='o', color='w', label='Scatter',\n                          markerfacecolor='g', markersize=15),\n                   Patch(facecolor='orange', edgecolor='r',\n                         label='Color Patch')]\n\n# Plot data and generate custom legend\nfig, ax = plt.subplots()\nax.legend(handles=legend_elements, loc='center')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-custom-matplotlib-projection-showcase":{"intro":"In this lab, we will learn how to create a custom projection using Matplotlib. We will be showcasing Hammer projection by alleviating many features of Matplotlib. We will be using Python as our programming language.","steps":[{"title":"Import Libraries","body":["First, we will import the necessary libraries to create a custom projection."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib\nfrom matplotlib.axes import Axes\nimport matplotlib.axis as maxis\nfrom matplotlib.patches import Circle\nfrom matplotlib.path import Path\nfrom matplotlib.projections import register_projection\nimport matplotlib.spines as mspines\nfrom matplotlib.ticker import FixedLocator, Formatter, NullLocator\nfrom matplotlib.transforms import Affine2D, BboxTransformTo, Transform"}]},{"title":"Create GeoAxes Class","body":["We will create an abstract base class for geographic projections called GeoAxes."],"code":[{"lang":"python","text":"class GeoAxes(Axes):\n    \"\"\"\n    An abstract base class for geographic projections\n    \"\"\"\n\n    class ThetaFormatter(Formatter):\n        \"\"\"\n        Used to format the theta tick labels.  Converts the native\n        unit of radians into degrees and adds a degree symbol.\n        \"\"\"\n        def __init__(self, round_to=1.0):\n            self._round_to = round_to\n\n        def __call__(self, x, pos=None):\n            degrees = round(np.rad2deg(x) / self._round_to) * self._round_to\n            return f\"{degrees:0.0f}\\N{DEGREE SIGN}\"\n\n    RESOLUTION = 75\n\n    def _init_axis(self):\n        self.xaxis = maxis.XAxis(self)\n        self.yaxis = maxis.YAxis(self)\n        # Do not register xaxis or yaxis with spines -- as done in\n        # Axes._init_axis() -- until GeoAxes.xaxis.clear() works.\n        # self.spines['geo'].register_axis(self.yaxis)\n\n    def clear(self):\n        # docstring inherited\n        super().clear()\n\n        self.set_longitude_grid(30)\n        self.set_latitude_grid(15)\n        self.set_longitude_grid_ends(75)\n        self.xaxis.set_minor_locator(NullLocator())\n        self.yaxis.set_minor_locator(NullLocator())\n        self.xaxis.set_ticks_position('none')\n        self.yaxis.set_ticks_position('none')\n        self.yaxis.set_tick_params(label1On=True)\n        # Why do we need to turn on yaxis tick labels, but\n        # xaxis tick labels are already on?\n\n        self.grid(rcParams['axes.grid'])\n\n        Axes.set_xlim(self, -np.pi, np.pi)\n        Axes.set_ylim(self, -np.pi / 2.0, np.pi / 2.0)"}]},{"title":"Create HammerAxes Class","body":["We will create a custom class for the Aitoff-Hammer projection, an equal-area map projection called HammerAxes."],"code":[{"lang":"python","text":"class HammerAxes(GeoAxes):\n    \"\"\"\n    A custom class for the Aitoff-Hammer projection, an equal-area map\n    projection.\n\n    https://en.wikipedia.org/wiki/Hammer_projection\n    \"\"\"\n\n    # The projection must specify a name. This will be used by the\n    # user to select the projection,\n    # i.e. ``subplot(projection='custom_hammer')``.\n    name = 'custom_hammer'\n\n    class HammerTransform(Transform):\n        \"\"\"The base Hammer transform.\"\"\"\n        input_dims = output_dims = 2\n\n        def __init__(self, resolution):\n            \"\"\"\n            Create a new Hammer transform.  Resolution is the number of steps\n            to interpolate between each input line segment to approximate its\n            path in curved Hammer space.\n            \"\"\"\n            Transform.__init__(self)\n            self._resolution = resolution\n\n        def transform_non_affine(self, ll):\n            longitude, latitude = ll.T\n\n            # Pre-compute some values\n            half_long = longitude / 2\n            cos_latitude = np.cos(latitude)\n            sqrt2 = np.sqrt(2)\n\n            alpha = np.sqrt(1 + cos_latitude * np.cos(half_long))\n            x = (2 * sqrt2) * (cos_latitude * np.sin(half_long)) / alpha\n            y = (sqrt2 * np.sin(latitude)) / alpha\n            return np.column_stack([x, y])\n\n        def transform_path_non_affine(self, path):\n            # vertices = path.vertices\n            ipath = path.interpolated(self._resolution)\n            return Path(self.transform(ipath.vertices), ipath.codes)\n\n        def inverted(self):\n            return HammerAxes.InvertedHammerTransform(self._resolution)\n\n    class InvertedHammerTransform(Transform):"}]},{"title":"Register Projection","body":["Now we will register the projection with Matplotlib so the user can select it."],"code":[{"lang":"python","text":"register_projection(HammerAxes)"}]},{"title":"Create Example","body":["Finally, we will create an example using the custom projection."],"code":[{"lang":"python","text":"if __name__ == '__main__':\n    import matplotlib.pyplot as plt\n\n    # Now make a simple example using the custom projection.\n    fig, ax = plt.subplots(subplot_kw={'projection': 'custom_hammer'})\n    ax.plot([-1, 1, 1], [-1, -1, 1], \"o-\")\n    ax.grid()\n\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == '__main__':\n    import matplotlib.pyplot as plt\n\n    # Now make a simple example using the custom projection.\n    fig, ax = plt.subplots(subplot_kw={'projection': 'custom_hammer'})\n    ax.plot([-1, 1, 1], [-1, -1, 1], \"o-\")\n    ax.grid()\n\n    plt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-custom-mercator-latitude-scale-in-matplotlib":{"intro":"Matplotlib is a powerful data visualization library for Python. It provides a number of built-in scales for plotting data, but sometimes you may need a custom scale for your specific use case. In this lab, we will show you how to create a custom scale that uses the Mercator projection for latitude data.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import numpy as np\nfrom numpy import ma\n\nfrom matplotlib import scale as mscale\nfrom matplotlib import transforms as mtransforms\nfrom matplotlib.ticker import FixedLocator, FuncFormatter"}]},{"title":"Define the MercatorLatitudeScale class","body":["Define the MercatorLatitudeScale class","Next, we will define the MercatorLatitudeScale class that will implement the custom scale. This class will inherit from mscale.ScaleBase."],"code":[{"lang":"python","text":"class MercatorLatitudeScale(mscale.ScaleBase):\n    \"\"\"\n    Scales data in range -pi/2 to pi/2 (-90 to 90 degrees) using\n    the system used to scale latitudes in a Mercator__ projection.\n\n    The scale function:\n      ln(tan(y) + sec(y))\n\n    The inverse scale function:\n      atan(sinh(y))\n\n    Since the Mercator scale tends to infinity at +/- 90 degrees,\n    there is user-defined threshold, above and below which nothing\n    will be plotted.  This defaults to +/- 85 degrees.\n\n    __ https://en.wikipedia.org/wiki/Mercator_projection\n    \"\"\""}]},{"title":"Implement the MercatorLatitudeTransform class","body":["Implement the MercatorLatitudeTransform class","Inside the MercatorLatitudeScale class, we will define the MercatorLatitudeTransform class that will actually transform the data. This class will inherit from mtransforms.Transform."],"code":[{"lang":"python","text":"class MercatorLatitudeTransform(mtransforms.Transform):\n        # There are two value members that must be defined.\n        # ``input_dims`` and ``output_dims`` specify number of input\n        # dimensions and output dimensions to the transformation.\n        # These are used by the transformation framework to do some\n        # error checking and prevent incompatible transformations from\n        # being connected together.  When defining transforms for a\n        # scale, which are, by definition, separable and have only one\n        # dimension, these members should always be set to 1.\n        input_dims = output_dims = 1\n\n        def __init__(self, thresh):\n            mtransforms.Transform.__init__(self)\n            self.thresh = thresh\n\n        def transform_non_affine(self, a):\n            \"\"\"\n            This transform takes a numpy array and returns a transformed copy.\n            Since the range of the Mercator scale is limited by the\n            user-specified threshold, the input array must be masked to\n            contain only valid values.  Matplotlib will handle masked arrays\n            and remove the out-of-range data from the plot.  However, the\n            returned array *must* have the same shape as the input array, since\n            these values need to remain synchronized with values in the other\n            dimension.\n            \"\"\"\n            masked = ma.masked_where((a < -self.thresh) | (a > self.thresh), a)\n            if masked.mask.any():\n                return ma.log(np.abs(ma.tan(masked) + 1 / ma.cos(masked)))\n            else:\n                return np.log(np.abs(np.tan(a) + 1 / np.cos(a)))\n\n        def inverted(self):\n            \"\"\"\n            Override this method so Matplotlib knows how to get the\n            inverse transform for this transform.\n            \"\"\"\n            return MercatorLatitudeScale.InvertedMercatorLatitudeTransform(\n                self.thresh)"}]},{"title":"Implement the InvertedMercatorLatitudeTransform class","body":["Implement the InvertedMercatorLatitudeTransform class","We will also define the InvertedMercatorLatitudeTransform class that will be used to get the inverse transform for this scale."],"code":[{"lang":"python","text":"class InvertedMercatorLatitudeTransform(mtransforms.Transform):\n        input_dims = output_dims = 1\n\n        def __init__(self, thresh):\n            mtransforms.Transform.__init__(self)\n            self.thresh = thresh\n\n        def transform_non_affine(self, a):\n            return np.arctan(np.sinh(a))\n\n        def inverted(self):\n            return MercatorLatitudeScale.MercatorLatitudeTransform(self.thresh)"}]},{"title":"Register the custom scale","body":["We will register the custom scale with Matplotlib using mscale.register_scale."],"code":[{"lang":"python","text":"mscale.register_scale(MercatorLatitudeScale)"}]},{"title":"Use the custom scale","body":["Now we can use the custom scale in our plots. Here's an example of using the custom scale for latitude data in a Mercator projection."],"code":[{"lang":"python","text":"if __name__ == '__main__':\n    import matplotlib.pyplot as plt\n\n    t = np.arange(-180.0, 180.0, 0.1)\n    s = np.radians(t)/2.\n\n    plt.plot(t, s, '-', lw=2)\n    plt.yscale('mercator')\n\n    plt.xlabel('Longitude')\n    plt.ylabel('Latitude')\n    plt.title('Mercator projection')\n    plt.grid(True)\n\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == '__main__':\n    import matplotlib.pyplot as plt\n\n    t = np.arange(-180.0, 180.0, 0.1)\n    s = np.radians(t)/2.\n\n    plt.plot(t, s, '-', lw=2)\n    plt.yscale('mercator')\n\n    plt.xlabel('Longitude')\n    plt.ylabel('Latitude')\n    plt.title('Mercator projection')\n    plt.grid(True)\n\n    plt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-custom-hillshading-in-a-3d-surface-plot":{"intro":"This lab demonstrates how to use custom hillshading in a 3D surface plot using Python Matplotlib. Hillshading is the use of light and shadow to enhance the perception of depth and relief in a 3D plot. By customizing the hillshading, we can create a more visually appealing and informative plot.","steps":[{"title":"Load and format data","body":["In this step, we will load and format the data for the 3D surface plot. We will be using a sample dataset called \"jacksboro_fault_dem.npz\"."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib import cbook, cm\nfrom matplotlib.colors import LightSource\n\n# Load and format data\ndem = cbook.get_sample_data('jacksboro_fault_dem.npz')\nz = dem['elevation']\nnrows, ncols = z.shape\nx = np.linspace(dem['xmin'], dem['xmax'], ncols)\ny = np.linspace(dem['ymin'], dem['ymax'], nrows)\nx, y = np.meshgrid(x, y)\n\nregion = np.s_[5:50, 5:50]\nx, y, z = x[region], y[region], z[region]"}]},{"title":"Set up plot","body":["In this step, we will set up the plot for the 3D surface plot. We will be using a LightSource object to customize the hillshading."],"code":[{"lang":"python","text":"# Set up plot\nfig, ax = plt.subplots(subplot_kw=dict(projection='3d'))\n\nls = LightSource(270, 45)\n# To use a custom hillshading mode, override the built-in shading and pass\n# in the rgb colors of the shaded surface calculated from \"shade\".\nrgb = ls.shade(z, cmap=cm.gist_earth, vert_exag=0.1, blend_mode='soft')\nsurf = ax.plot_surface(x, y, z, rstride=1, cstride=1, facecolors=rgb,\n                       linewidth=0, antialiased=False, shade=False)\n\nplt.show()"}]},{"title":"Customize Hillshading","body":["In this step, we will customize the hillshading by overriding the built-in shading and passing in the RGB colors of the shaded surface calculated from \"shade\"."],"code":[{"lang":"python","text":"# Set up plot\nfig, ax = plt.subplots(subplot_kw=dict(projection='3d'))\n\nls = LightSource(270, 45)\n# To use a custom hillshading mode, override the built-in shading and pass\n# in the rgb colors of the shaded surface calculated from \"shade\".\nrgb = ls.shade(z, cmap=cm.gist_earth, vert_exag=0.1, blend_mode='soft')\nsurf = ax.plot_surface(x, y, z, rstride=1, cstride=1, facecolors=rgb,\n                       linewidth=0, antialiased=False, shade=False)\n\nplt.show()"}]},{"title":"Review and revise","body":["Review the code and make any necessary revisions. Ensure that the code is accurate and well-commented."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-custom-matplotlib-ticker-formatting":{"intro":"In this lab, you will learn how to create a custom ticker in Python Matplotlib using the ticker module. The custom ticker will format the y-axis ticks in millions of dollars.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries to create the custom ticker. We need the pyplot and ticker modules from Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.ticker as ticker"}]},{"title":"Define Custom Ticker Function","body":["Next, we need to define the custom ticker function. The custom ticker function takes two arguments - the value and tick position - and returns the formatted tick label. In this case, we will format the tick label as dollars in millions."],"code":[{"lang":"python","text":"def millions(x, pos):\n    \"\"\"The two arguments are the value and tick position.\"\"\"\n    return f'${x*1e-6:1.1f}M'"}]},{"title":"Create the Plot","body":["Now, we can create the plot with the custom ticker. We will create a bar chart with sample data and set the y-axis ticker to use our custom ticker function."],"code":[{"lang":"python","text":"# Create a bar chart with sample data\nfig, ax = plt.subplots()\nmoney = [1.5e5, 2.5e6, 5.5e6, 2.0e7]\nax.bar(['Bill', 'Fred', 'Mary', 'Sue'], money)\n\n# Set the y-axis ticker to use the custom ticker function\nax.yaxis.set_major_formatter(ticker.FuncFormatter(millions))\n\n# Display the plot\nplt.show()"}]},{"title":"Interpret the Output","body":["The output of the code should be a bar chart with the y-axis labels formatted in millions of dollars. The tick labels will be formatted as $0.2M, $2.5M, $5.5M, and $20.0M respectively."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-defaults-with-python":{"intro":"This lab will guide you through the process of customizing .rcParams on the fly using Python Matplotlib. You will learn how to define functions in a custom module that set the defaults for figures, and how to use these defaults to create different sets of defaults for figures, such as one set for publication and another set for interactive exploration.","steps":[{"title":"Create a Function to Set Default Parameters","body":["Create a Function to Set Default Parameters","To create a function that sets the default parameters for your figures, you can use the rcParams.update() method. This method takes a dictionary of parameter names and values, and updates the current default values with the new ones. Here's an example of a function that sets some default parameters for publication figures:"],"code":[{"lang":"python","text":"def set_pub():\n    rcParams.update({\n        \"font.weight\": \"bold\",  # bold fonts\n        \"tick.labelsize\": 15,   # large tick labels\n        \"lines.linewidth\": 1,   # thick lines\n        \"lines.color\": \"k\",     # black lines\n        \"grid.color\": \"0.5\",    # gray gridlines\n        \"grid.linestyle\": \"-\",  # solid gridlines\n        \"grid.linewidth\": 0.5,  # thin gridlines\n        \"savefig.dpi\": 300,     # higher resolution output.\n    })"}]},{"title":"Customize Default Parameters","body":["To customize the default parameters for a specific figure, you can use the rcParams.update() method again. This time, you'll pass a dictionary of parameter names and values that you want to set for that figure. Here's an example that sets some default parameters for a specific figure:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.rcParams.update({\n    \"font.weight\": \"bold\",\n    \"xtick.major.size\": 5,\n    \"xtick.major.pad\": 7,\n    \"xtick.labelsize\": 15,\n    \"grid.color\": \"0.5\",\n    \"grid.linestyle\": \"-\",\n    \"grid.linewidth\": 5,\n    \"lines.linewidth\": 2,\n    \"lines.color\": \"g\",\n})"}]},{"title":"Create Subplots","body":["To create subplots in Matplotlib, you can use the subplot() method. This method takes three arguments: the number of rows, the number of columns, and the plot number. Here's an example that creates three subplots:"],"code":[{"lang":"python","text":"plt.subplot(311)\nplt.plot([1, 2, 3])\n\nplt.subplot(312)\nplt.plot([1, 2, 3])\nplt.grid(True)\n\nplt.subplot(313)\nplt.plot([1, 2, 3])\nplt.grid(True)"}]},{"title":"Show the Figure","body":["To show the figure, you can use the show() method. Here's an example:"],"code":[{"lang":"python","text":"plt.show()"}]},{"title":"Reset Default Parameters","body":["To reset the default parameters to their original values, you can use the rcdefaults() method. Here's an example:"],"code":[{"lang":"python","text":"plt.rcdefaults()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.rcdefaults()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-violin-plot-visualizations":{"intro":"In this lab, we will learn how to customize violin plots using Matplotlib. Violin plots are a powerful tool for visualizing the distribution and density of data. By customizing the appearance of the plot, we can create more informative and visually appealing visualizations.","steps":[{"title":"Create test data","body":["First, we will create some test data to use for the violin plot. We will use NumPy to generate four arrays of 100 normally distributed values with increasing standard deviations."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create test data\nnp.random.seed(19680801)\ndata = [sorted(np.random.normal(0, std, 100)) for std in range(1, 5)]"}]},{"title":"Create a default violin plot","body":["Next, we will create a default violin plot using Matplotlib's violinplot function. This will provide a baseline for comparison when we customize the plot in later steps."],"code":[{"lang":"python","text":"# create default violin plot\nfig, ax1 = plt.subplots()\nax1.set_title('Default Violin Plot')\nax1.set_ylabel('Observed Values')\nax1.violinplot(data)"}]},{"title":"Customize the violin plot appearance","body":["Customize the violin plot appearance","Now we will customize the appearance of the violin plot. First, we will limit what Matplotlib draws by setting the showmeans, showmedians, and showextrema arguments to False. Then, we will change the color and opacity of the violin bodies using the set_facecolor and set_alpha methods. Finally, we will add a simplified representation of a box plot on top of the violin plot, using the percentile function from NumPy to calculate the quartiles, medians, and whiskers."],"code":[{"lang":"python","text":"# customize violin plot appearance\nfig, ax2 = plt.subplots()\nax2.set_title('Customized Violin Plot')\nax2.set_ylabel('Observed Values')\n\n# create violin plot\nparts = ax2.violinplot(\n        data, showmeans=False, showmedians=False,\n        showextrema=False)\n\n# customize violin bodies\nfor pc in parts['bodies']:\n    pc.set_facecolor('#D43F3A')\n    pc.set_edgecolor('black')\n    pc.set_alpha(1)\n\n# add box plot\nquartile1, medians, quartile3 = np.percentile(data, [25, 50, 75], axis=1)\nwhiskers = np.array([\n    adjacent_values(sorted_array, q1, q3)\n    for sorted_array, q1, q3 in zip(data, quartile1, quartile3)])\nwhiskers_min, whiskers_max = whiskers[:, 0], whiskers[:, 1]\n\ninds = np.arange(1, len(medians) + 1)\nax2.scatter(inds, medians, marker='o', color='white', s=30, zorder=3)\nax2.vlines(inds, quartile1, quartile3, color='k', linestyle='-', lw=5)\nax2.vlines(inds, whiskers_min, whiskers_max, color='k', linestyle='-', lw=1)"}]},{"title":"Set axis style","body":["Finally, we will set the style for the x-axis by specifying the tick labels and limits. We will define a helper function set_axis_style to accomplish this."],"code":[{"lang":"python","text":"# set style for the axes\nlabels = ['A', 'B', 'C', 'D']\nset_axis_style(ax2, labels)\n\ndef set_axis_style(ax, labels):\n    ax.set_xticks(np.arange(1, len(labels) + 1))\n    ax.set_xticklabels(labels)\n    ax.set_xlim(0.25, len(labels) + 0.75)\n    ax.set_xlabel('Sample Name')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# set style for the axes\nlabels = ['A', 'B', 'C', 'D']\nset_axis_style(ax2, labels)\n\ndef set_axis_style(ax, labels):\n    ax.set_xticks(np.arange(1, len(labels) + 1))\n    ax.set_xticklabels(labels)\n    ax.set_xlim(0.25, len(labels) + 0.75)\n    ax.set_xlabel('Sample Name')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-using-the-dark-background-style-s":{"intro":"Matplotlib is a data visualization library used for creating static, animated, and interactive visualizations in Python. In this lab, we will learn how to use the 'dark_background' style sheet in Matplotlib to create plots with a dark background. The dark background style sheet is particularly useful for displaying visualizations that are easy on the eyes in low-light environments.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. We will be using the Matplotlib library to create our visualizations and the NumPy library to generate some sample data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set the 'dark_background' Style Sheet","body":["Set the 'dark_background' Style Sheet","The next step is to set the 'dark_background' style sheet using the plt.style.use() function. This will apply the dark background style to all plots that we create from this point onwards."],"code":[{"lang":"python","text":"plt.style.use('dark_background')"}]},{"title":"Create Sample Data","body":["In this step, we will generate some sample data to plot. We will create a sine wave with a wavelength of 6 units and plot it over the x-axis."],"code":[{"lang":"python","text":"L = 6\nx = np.linspace(0, L)"}]},{"title":"Plot the Data","body":["In this step, we will plot the sample data that we generated in the previous step. We will use a for loop to plot multiple sine waves with different phases."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nncolors = len(plt.rcParams['axes.prop_cycle'])\nshift = np.linspace(0, L, ncolors, endpoint=False)\n\nfor s in shift:\n    # Plot the sine wave with a phase shift of s\n    ax.plot(x, np.sin(x + s), 'o-')\n\nax.set_xlabel('x-axis')\nax.set_ylabel('y-axis')\nax.set_title(\"'dark_background' style sheet\")\n\nplt.show()"}]},{"title":"Interpret the Plot","body":["The plot that we created in the previous step is a sine wave with a dark background. The for loop plots multiple sine waves with different phases, which are shifted along the x-axis. The x-axis represents the values of the sine wave, while the y-axis represents the amplitude of the sine wave. The set_xlabel(), set_ylabel(), and set_title() functions are used to label the x-axis, y-axis, and title of the plot, respectively."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-interactive-data-visualization-with-python-m":{"intro":"This lab will walk you through how to interact data with multiple canvases. By selecting and highlighting a point on one axis, you will generate the data of that point on the other axis. We will be using Python Matplotlib for this lab.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Generate Data","body":["We will generate random data using NumPy."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nX = np.random.rand(100, 200)\nxs = np.mean(X, axis=1)\nys = np.std(X, axis=1)"}]},{"title":"Create Figure and Axes","body":["We will create a figure with two axes."],"code":[{"lang":"python","text":"fig, (ax, ax2) = plt.subplots(2, 1)"}]},{"title":"Plot Data","body":["We will plot the generated data on the first axis."],"code":[{"lang":"python","text":"line, = ax.plot(xs, ys, 'o', picker=True, pickradius=5)"}]},{"title":"Create Point Browser Class","body":["We will create a class to handle the point browser functionality."],"code":[{"lang":"python","text":"class PointBrowser:\n    def __init__(self):\n        self.lastind = 0\n\n        self.text = ax.text(0.05, 0.95, 'selected: none',\n                            transform=ax.transAxes, va='top')\n        self.selected, = ax.plot([xs[0]], [ys[0]], 'o', ms=12, alpha=0.4,\n                                 color='yellow', visible=False)\n\n    def on_press(self, event):\n        if self.lastind is None:\n            return\n        if event.key not in ('n', 'p'):\n            return\n        if event.key == 'n':\n            inc = 1\n        else:\n            inc = -1\n\n        self.lastind += inc\n        self.lastind = np.clip(self.lastind, 0, len(xs) - 1)\n        self.update()\n\n    def on_pick(self, event):\n\n        if event.artist != line:\n            return True\n\n        N = len(event.ind)\n        if not N:\n            return True\n\n        # the click locations\n        x = event.mouseevent.xdata\n        y = event.mouseevent.ydata\n\n        distances = np.hypot(x - xs[event.ind], y - ys[event.ind])\n        indmin = distances.argmin()\n        dataind = event.ind[indmin]\n\n        self.lastind = dataind\n        self.update()\n\n    def update(self):\n        if self.lastind is None:\n            return\n\n        dataind = self.lastind"}]},{"title":"Connect Event Handlers","body":["We will connect the event handlers to the figure canvas."],"code":[{"lang":"python","text":"browser = PointBrowser()\n\nfig.canvas.mpl_connect('pick_event', browser.on_pick)\nfig.canvas.mpl_connect('key_press_event', browser.on_press)"}]},{"title":"Display Plot","body":[],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-date-plotting":{"intro":"In this lab, we will learn how to create date plots using Matplotlib in Python. We will use the matplotlib.dates module to convert datetime objects to Matplotlib's internal representation. We will also learn how to format the tick labels on the x-axis to display dates in a readable format.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries, including matplotlib.pyplot, matplotlib.cbook, and matplotlib.dates."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.cbook as cbook\nimport matplotlib.dates as mdates"}]},{"title":"Load data","body":["Next, we will load the data that we want to plot. We will use a numpy record array from Yahoo csv data with fields date, open, high, low, close, volume, adj_close from the mpl-data/sample_data directory. The record array stores the date as an np.datetime64 with a day unit ('D') in the date column."],"code":[{"lang":"python","text":"data = cbook.get_sample_data('goog.npz')['price_data']"}]},{"title":"Create subplots","body":["We will create three subplots to show different formatting options for the tick labels."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(3, 1, figsize=(6.4, 7), layout='constrained')"}]},{"title":"Plot data","body":["We will plot the data on all three subplots using the plot function."],"code":[{"lang":"python","text":"for ax in axs:\n    ax.plot('date', 'adj_close', data=data)\n    ax.grid(True)\n    ax.set_ylabel(r'Price [\\$]')"}]},{"title":"Format tick labels using default formatter","body":["Format tick labels using default formatter","We will format the tick labels on the first subplot using the default formatter."],"code":[{"lang":"python","text":"ax = axs[0]\nax.set_title('DefaultFormatter', loc='left', y=0.85, x=0.02, fontsize='medium')\nax.xaxis.set_major_locator(mdates.MonthLocator(bymonth=(1, 7)))\nax.xaxis.set_minor_locator(mdates.MonthLocator())"}]},{"title":"Format tick labels using concise formatter","body":["Format tick labels using concise formatter","We will format the tick labels on the second subplot using the concise formatter."],"code":[{"lang":"python","text":"ax = axs[1]\nax.set_title('ConciseFormatter', loc='left', y=0.85, x=0.02, fontsize='medium')\nax.xaxis.set_major_formatter(mdates.ConciseDateFormatter(ax.xaxis.get_major_locator()))"}]},{"title":"Format tick labels manually","body":["We will format the tick labels on the third subplot manually using DateFormatter to format the dates using the format strings documented at datetime.date.strftime."],"code":[{"lang":"python","text":"ax = axs[2]\nax.set_title('Manual DateFormatter', loc='left', y=0.85, x=0.02, fontsize='medium')\nax.xaxis.set_major_formatter(mdates.DateFormatter('%Y-%b'))\nfor label in ax.get_xticklabels(which='major'):\n    label.set(rotation=30, horizontalalignment='right')"}]},{"title":"Display plot","body":["Finally, we will display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"}};
